test "duplicate out-of-root entry scans once and deinits leak-free (EPH-I0817)" {
    // A repeated entry string (--entry twice, a config list with a
    // repeat) must scan the file once: a second analyzeFile overwrites
    // the first graph entry and leaks the replaced value and the stored
    // key. std.testing.allocator turns every leak into a FAIL.
    var diag = testDiagCtx();
    diag.cli_diagnostics_enabled = false;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDirPath(std.testing.io, "src");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "src/main.zig",
        .data = "pub fn main() void {}\n",
    });
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "entry.zig",
        .data = "pub fn main() void {}\n",
    });
    const tmp_path = try tmpDirPath(allocator, &tmp);
    defer allocator.free(tmp_path);
    const src_path = try std.fmt.allocPrint(allocator, "{s}/src", .{tmp_path});
    defer allocator.free(src_path);
    const entry_path = try std.fmt.allocPrint(allocator, "{s}/entry.zig", .{tmp_path});
    defer allocator.free(entry_path);

    var cfg = testConfig();
    defer cfg.deinit(allocator);
    try setOwnedPath(allocator, &cfg, src_path);
    try cfg.entries.append(allocator, try allocator.dupe(u8, entry_path));
    try cfg.entries.append(allocator, try allocator.dupe(u8, entry_path));
    var cache = IgnoreCache.init(allocator);
    defer cache.deinit();
    var run = SpellingRun.init(&diag, allocator, &cfg, &cache);
    defer run.deinit();

    try buildCheckGraph(&run.ctx, &run.graph);

    // One join per physical file: the repeat never adds a graph entry.
    try std.testing.expectEqual(@as(usize, 2), run.graph.files.count());
    // The widen note still counts occurrences (EPH-I0802 upper bound):
    // the dedupe changes joins, not the note's count semantics.
    try std.testing.expectEqual(@as(usize, 1), diag.entries_widen_note_count);
}

test "alternate out-of-root entry spellings scan once (EPH-I0817)" {
    // Two spellings of one physical file outside the scan path collapse
    // to one scan. Pre-fix the second analyzeFile joined the file under
    // a second graph key (duplicate analysis, stale resolved_to_key
    // value); the realpath-keyed dedupe pins the graph to one entry.
    var diag = testDiagCtx();
    diag.cli_diagnostics_enabled = false;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDirPath(std.testing.io, "src");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "src/main.zig",
        .data = "pub fn main() void {}\n",
    });
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "entry.zig",
        .data = "pub fn main() void {}\n",
    });
    const tmp_path = try tmpDirPath(allocator, &tmp);
    defer allocator.free(tmp_path);
    const src_path = try std.fmt.allocPrint(allocator, "{s}/src", .{tmp_path});
    defer allocator.free(src_path);
    const entry_path = try std.fmt.allocPrint(allocator, "{s}/entry.zig", .{tmp_path});
    defer allocator.free(entry_path);
    const infix_entry_path = try std.fmt.allocPrint(allocator, "{s}/./entry.zig", .{tmp_path});
    defer allocator.free(infix_entry_path);

    var cfg = testConfig();
    defer cfg.deinit(allocator);
    try setOwnedPath(allocator, &cfg, src_path);
    try cfg.entries.append(allocator, try allocator.dupe(u8, entry_path));
    try cfg.entries.append(allocator, try allocator.dupe(u8, infix_entry_path));
    var cache = IgnoreCache.init(allocator);
    defer cache.deinit();
    var run = SpellingRun.init(&diag, allocator, &cfg, &cache);
    defer run.deinit();

    try buildCheckGraph(&run.ctx, &run.graph);

    try std.testing.expectEqual(@as(usize, 2), run.graph.files.count());
    try std.testing.expectEqual(@as(usize, 1), diag.entries_widen_note_count);
}

test "walk joins one graph entry per physical hardlink (EPH-I0823)" {
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    // One physical file under two names: a hardlink pair. The walk sees
    // two .file entries with one inode; the pair must join the graph
    // once. Duplicate analysis and duplicate findings are the bug.
    try tmp.dir.createDirPath(std.testing.io, "a/link");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "a/x.zig",
        .data = "pub fn f() void {}\n",
    });
    try tmp.dir.hardLink("a/x.zig", tmp.dir, "a/link/x.zig", std.testing.io, .{});
    // A symlinked dir adds no joins: the walk skips .sym_link entries.
    // Pinning the no-duplicate rule for the alternate shape too.
    try tmp.dir.symLink(std.testing.io, "a", "linkdir", .{ .is_directory = true });
    try tmp.dir.createDirPath(std.testing.io, "b");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "b/y.zig",
        .data = "pub fn g() void {}\n",
    });

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();
    const root = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(root);
    try graph.scanDirectory(root);

    // Two physical files join once each.
    try std.testing.expectEqual(@as(usize, 2), graph.files.count());
    // The hardlink pair contributes exactly one graph key.
    var x_keys: usize = 0;
    var iter = graph.files.keyIterator();
    while (iter.next()) |key| {
        if (mem.endsWith(u8, key.*, "x.zig")) x_keys += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), x_keys);

    // Findings stay one per physical file: two orphan rows, not three.
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    var issues = try graph.getOrphanIssues(allocator, &cfg);
    defer deinitIssues(&issues, allocator);
    try std.testing.expectEqual(@as(usize, 2), issues.items.len);
}

test "inode gate bound: inode-only key, inode 0 bypass (EPH-I0828)" {
    // The multi-device bound at walked_file_inodes holds only while
    // std.Io has no device identity. Verify that claim against the
    // stdlib in use. When Zig adds a device field, the compile errors
    // fire: that is the signal to implement the (device, inode) gate
    // arm and close the bound.
    if (@hasField(std.Io.File.Stat, "dev"))
        @compileError("std.Io.File.Stat has dev: implement (device, inode) gate arm (EPH-I0828)");
    if (@hasField(std.Io.Dir.Stat, "dev"))
        @compileError("std.Io.Dir.Stat has dev: implement (device, inode) gate arm (EPH-I0828)");
    if (@hasField(std.Io.Dir.Entry, "dev"))
        @compileError("std.Io.Dir.Entry has dev: implement (device, inode) gate arm (EPH-I0828)");

    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();

    // Inode 0 never joins the gate: filesystems that report 0 for
    // every entry must not collapse distinct files.
    try std.testing.expect(!(try graph.walkFileAlreadyScanned(0)));
    try std.testing.expect(!(try graph.walkFileAlreadyScanned(0)));

    // The first spelling of an inode joins the graph.
    try std.testing.expect(!(try graph.walkFileAlreadyScanned(42)));
    // The second spelling of the same inode is a duplicate.
    try std.testing.expect(try graph.walkFileAlreadyScanned(42));
    // A different inode is a distinct physical file.
    try std.testing.expect(!(try graph.walkFileAlreadyScanned(43)));
}

test "corpus warning fires once when resident bytes cross the threshold" {
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    diag.corpus_bytes_warn_threshold = 1024;
    diag.cli_diagnostics_enabled = false;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const pad_a = try allocator.alloc(u8, 600);
    defer allocator.free(pad_a);
    @memset(pad_a, 'a');
    const pad_b = try allocator.alloc(u8, 700);
    defer allocator.free(pad_b);
    @memset(pad_b, 'b');
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "a.zig", .data = pad_a });
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "b.zig", .data = pad_b });
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "c.zig", .data = pad_a });

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();
    const path_a = try tmpFilePath(allocator, &tmp, "a.zig");
    defer allocator.free(path_a);
    const path_b = try tmpFilePath(allocator, &tmp, "b.zig");
    defer allocator.free(path_b);
    const path_c = try tmpFilePath(allocator, &tmp, "c.zig");
    defer allocator.free(path_c);

    // 600 < 1024: under the threshold, no warning.
    try graph.analyzeFile(path_a);
    try std.testing.expectEqual(@as(usize, 600), graph.resident_bytes);
    try std.testing.expectEqual(@as(usize, 0), diag.corpus_warn_count);
    // 600 + 700 = 1300 > 1024: the crossing fires the warning once.
    try graph.analyzeFile(path_b);
    try std.testing.expectEqual(@as(usize, 1300), graph.resident_bytes);
    try std.testing.expectEqual(@as(usize, 1), diag.corpus_warn_count);
    // Past the threshold the edge trigger holds: no second warning.
    try graph.analyzeFile(path_c);
    try std.testing.expectEqual(@as(usize, 1), diag.corpus_warn_count);
}

test "markAllZigFilesReachable memoizes overlapping roots" {
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    // inner is a nested sub-project root: the outer walk covers it, and
    // the inner walk must not re-walk the shared subtree (EPH-I0204).
    try tmp.dir.createDirPath(std.testing.io, "src/inner/deep");
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "build.zig", .data = "" });
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "src/top.zig", .data = "" });
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "src/inner/build.zig", .data = "" });
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "src/inner/deep/x.zig", .data = "" });

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();
    const root = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(root);
    const inner = try tmpFilePath(allocator, &tmp, "src/inner");
    defer allocator.free(inner);

    graph.markAllZigFilesReachable(root);
    const memo_after_first = graph.marked_dirs.count();
    try std.testing.expect(memo_after_first > 1);
    graph.markAllZigFilesReachable(inner);

    // The overlapping root added no new memo entries: the walk stopped at
    // the memo hit on inner.
    try std.testing.expectEqual(memo_after_first, graph.marked_dirs.count());
    // Coverage pin: every .zig file still lands in reachable.
    const top = try tmpFilePath(allocator, &tmp, "src/top.zig");
    defer allocator.free(top);
    const inner_build = try tmpFilePath(allocator, &tmp, "src/inner/build.zig");
    defer allocator.free(inner_build);
    const deep = try tmpFilePath(allocator, &tmp, "src/inner/deep/x.zig");
    defer allocator.free(deep);
    try std.testing.expect(graph.reachable.contains(top));
    try std.testing.expect(graph.reachable.contains(inner_build));
    try std.testing.expect(graph.reachable.contains(deep));
}

test "markZigFilesRecursive does not memoize a depth-capped dir" {
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
