        .{ .input = "FAIL /src/t.zig:9 boom", .rule = RULE_RUNTIME_TEST_FAILURE, .file = "/src/t.zig", .line = 9 },
        .{ .input = "thread 9 panic: bad /p.zig:3", .rule = RULE_RUNTIME_PANIC, .file = "/p.zig", .line = 3 },
    };
