test "runFmtCheck stays silent when zig fmt crashes on a hostile line (EPH-I0979)" {
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    // zig fmt's own parser stack-overflows (signal 11) on a single
    // line with 20K `or` keywords (~140 KB); the pinned 0.16.0
    // toolchain crashes deterministically and prints nothing before
    // the crash (probe 2026-08-14). The signal-killed child is not an
    // ephor analysis result, so the fmt band reports no ZR104 — the
    // EPH-I0722 empty-list protection stays on the .exited class (a
    // missing path, syntax errors), which the user can fix.
    // 20K tokens is 2x the measured 10K crash threshold.
    const hostile_or_tokens = 20000;
    var content: std.ArrayListUnmanaged(u8) = .empty;
    defer content.deinit(allocator);
    try content.appendSlice(allocator, "fn hostile(n: usize) bool {\n    if (n>0 ");
    for (0..hostile_or_tokens) |_| try content.appendSlice(allocator, "or n>0 ");
    try content.appendSlice(allocator, ") return true;\n    return false;\n}\n");
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "hostile.zig", .data = content.items });
    const path = try tmpFilePath(allocator, &tmp, "hostile.zig");
    defer allocator.free(path);

    var issues = try runFmtCheck(&diag, allocator, path);
    defer deinitIssues(&issues, allocator);

    try std.testing.expectEqual(@as(usize, 0), issues.items.len);
}

test "fmtTermMessage sanitizes hostile bytes in the error line" {
    const allocator = std.testing.allocator;
    const stderr = "x.zig:1:1: error: bad \x1b[2J\x01 path\nlater line\n";
    const msg = try fmtTermMessage(allocator, .{ .exited = 1 }, stderr);
    defer allocator.free(msg);

    // RED5: control bytes become visible '?' marks, never terminal
    // sequences, and only the first error line reaches the message.
    try std.testing.expectEqualStrings("x.zig:1:1: error: bad ?[2J? path", msg);
}

test "firstErrorLine anchors the error marker" {
    // EPH-I0766: the marker is the line prefix (IO failures) or the
    // ": error: " interior form (parse failures). A bare "error:"
    // substring match read a needs-format list line whose path carried
    // the substring as a diagnostic.
    const io_failure = "error: unable to format '/x': FileNotFound\n";
    try std.testing.expectEqualStrings(
        "error: unable to format '/x': FileNotFound",
        firstErrorLine(io_failure).?,
    );
    const parse_failure = "x.zig:1:1: error: expected ';'\n";
    try std.testing.expectEqualStrings(
        "x.zig:1:1: error: expected ';'",
        firstErrorLine(parse_failure).?,
    );
    // A needs-format list line is a bare path: no marker, even when the
    // path carries the "error:" substring.
    try std.testing.expect(firstErrorLine("/x/proj/error:dir/needsfmt.zig\n") == null);
    try std.testing.expect(firstErrorLine("note: no error here\n") == null);
    // A list line above a real diagnostic does not mask the diagnostic.
    const mixed = "/x/proj/error:dir/needsfmt.zig\nx.zig:1:1: error: bad\n";
    try std.testing.expectEqualStrings("x.zig:1:1: error: bad", firstErrorLine(mixed).?);
}

