    // The `_`-discard guard sliced the LHS as `if (a) { _` on the
    // same-line if form, so the fallthrough read it as a store.
    const content =
        \\fn in_if_discard(allocator: std.mem.Allocator, a: bool) !void {
        \\    const buf = try allocator.alloc(u8, 16);
        \\    if (a) { _ = buf[0]; }
        \\    _ = buf;
        \\}
