    // now owns the allocation. The ownership-capability rule must keep
    // this credit.
    const content =
        \\const Holder = struct {
        \\    buf: []u8,
        \\};
        \\fn store(self: *Holder, allocator: std.mem.Allocator) !void {
        \\    const buf = try allocator.alloc(u8, 64);
        \\    self.buf = buf;
        \\    _ = buf;
        \\}
    ;
