    try std.testing.expect(lineHasErrorReturnMarker("    !usize {"));
    try std.testing.expect(lineHasErrorReturnMarker("    !*Node {"));
    try std.testing.expect(lineHasErrorReturnMarker("    ![]u8 {"));
}

