        \\}
        \\const State = struct { field: []u8 = &.{} };
        \\fn normalize(s: []const u8) !void {
        \\    if (s.len == 0) return error.Empty;
        \\}
        \\fn isFatal(err: anyerror) bool {
        \\    return err == error.Empty;
        \\}
