    // following-block exit acceptance covers it (EPH-I0488).
    const content =
        \\fn deref_null_guard(p: ?*u8) ?*u8 {
        \\    if (p == null) {
        \\        return null;
        \\    }
        \\    const v = p.*;
        \\    return v;
        \\}
