test "analyzeCFGMemory ZA802 silent past a same-line braced-with-else guard (EPH-I0863)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

