test "directive matching tolerates CRLF line endings" {
    const content = "// ephor:ignore ZA201\r\nconst x = foo() catch {};\r\n";
    try std.testing.expect(isInlineDisabled(content, 2, "ZA201"));
    const bare = "// ephor:ignore\r\nconst x = foo() catch {};\r\n";
    try std.testing.expect(isInlineDisabled(bare, 2, "ZA202"));
}

test "ephor:ignore with trailing whitespace and no rule suppresses all rules" {
    // Any-whitespace-then-empty rest is a bare directive (old code was inert
    // on trailing space yet bare on trailing tab — now consistent).
    const space = "const x = foo() catch {}; // ephor:ignore \n";
    try std.testing.expect(isInlineDisabled(space, 1, "ZA201"));
    try std.testing.expect(isInlineDisabled(space, 1, "ZA101"));
    const tab = "const x = foo() catch {}; // ephor:ignore\t\n";
    try std.testing.expect(isInlineDisabled(tab, 1, "ZA201"));
    try std.testing.expect(isInlineDisabled(tab, 1, "ZA202"));
}

// ============================================================================
// IgnoreCache differential tests — cached verdicts must equal the reference
// isInlineDisabled scan for every (line, rule) pair of every fixture.
// ============================================================================

/// Nasty-case fixtures for the IgnoreCache differential test. Every fixture
/// is probed exhaustively: lines 0..EOF+2 crossed with the rule table.
const ignore_cache_fixtures = [_][]const u8{
    // same-line directive suppresses only that line/rule
    \\const x = foo() catch {}; // ephor:ignore ZA201
    \\const y = foo() catch {};
    ,
    // legacy same-line disable + disable-next-line variant (rule list only)
    \\const a = foo() catch {}; // ephor:disable ZA202
    \\// ephor:disable-next-line ZA203
    \\const b = val orelse unreachable;
    \\const c = val orelse unreachable;
    ,
    // scope directive over a fn with nested braces
    \\const before = foo() catch {};
    \\// ephor:ignore ZA201
    \\fn outer() void {
    \\    if (true) {
    \\        foo() catch {};
    \\    }
    \\    bar() catch {};
    \\}
    \\const after = baz() catch {};
    ,
    // unclosed scope at EOF
    \\// ephor:ignore ZA201
    \\fn unterminated() void {
    \\    foo() catch {};
    ,
    // comment-only directive as the last line (no following line)
    \\const a = foo() catch {};
    \\// ephor:ignore ZA201
    ,
    // file-level with rule at top of file
    \\// ephor:ignore-file ZA201
    \\const a = foo() catch {};
    \\fn f() void {
    \\    bar() catch {};
    \\}
    ,
    // bare file-level in a trailing comment
    \\const marker = 1; // ephor:ignore-file
    \\const a = foo() catch {};
    ,
    // file-level mid-file also suppresses lines before the directive
    \\const a = foo() catch {};
    \\// ephor:ignore-file ZC101
    \\const b = bar() catch {};
    ,
    // doc-comment and prose-comment non-directives
    \\/// ephor:ignore ZA201
    \\// NOTE: ephor:ignore ZA202
    \\const x = foo() catch {};
    ,
    // string-literal and code-mention non-directives
    \\const s = "// ephor:ignore ZA201";
    \\const t = "ephor:ignore-file";
    \\const has = mem.indexOf(u8, line, "ephor:ignore") != null;
    \\const a = foo() catch {};
    ,
    // CRLF line endings (explicit escapes; raw literals cannot hold \r)
    "// ephor:ignore ZA201\r\nfn f() void {\r\n    foo() catch {};\r\n}\r\nconst z = bar() catch {};\r\n",
    // multi-rule list with trailing prose; rule id buried in prose is inert
    \\// ephor:ignore ZA201 ZA305 because pre-checked
    \\const x = foo() catch {};
    \\// ephor:ignore because ZA202 is noisy
    \\const y = foo() catch {};
    ,
    // multiline-string body is string data, not directives
    \\const fixture =
    \\    \\// ephor:ignore-file
    \\    \\// ephor:ignore ZA201
    \\;
    \\const x = foo() catch {};
    ,
    // directive inside an active scope still self-suppresses for its rule
    \\// ephor:ignore ZA201
    \\fn f() void {
    \\    // ephor:ignore ZA202
    \\    foo() catch {};
    \\}
    \\bar() catch {};
    ,
    // balanced braces on the scope-open line: scope never activates
    \\// ephor:ignore ZA201
    \\const x = blk: { break :blk foo() catch {}; };
    \\bar() catch {};
    ,
    // brace inside a string on the would-be open line opens no scope: the
    // directive suppresses only the next line
    \\// ephor:ignore ZA201
    \\const s = "{";
    \\foo() catch {};
    \\}
    \\bar() catch {};
    ,
    // bare directive with trailing whitespace suppresses all rules
    "const x = foo() catch {}; // ephor:ignore \nconst y = foo() catch {};\n",
};

test "IgnoreCache matches isInlineDisabled on every (line, rule) pair" {
    const allocator = std.testing.allocator;
    const rules = [_][]const u8{ "ZA201", "ZA202", "ZA203", "ZA101", "ZA305", "ZC101" };
    for (ignore_cache_fixtures, 0..) |content, fixture_idx| {
        var cache = IgnoreCache.init(allocator);
        defer cache.deinit();
        // Probe line 0 and past EOF too: both implementations must agree there.
        const max_line = countLines(content) + 2;
        var line_num: usize = 0;
        while (line_num <= max_line) : (line_num += 1) {
            for (rules) |rule| {
                const want = isInlineDisabled(content, line_num, rule);
                const got = cache.isSuppressed(content, "fixture.zig", line_num, rule);
                if (want == got) continue;
                std.debug.print(
                    "IgnoreCache mismatch: fixture {d} line {d} rule {s}: " ++
                        "isInlineDisabled={} cache={}\n",
                    .{ fixture_idx, line_num, rule, want, got },
                );
                return error.IgnoreCacheMismatch;
            }
        }
    }
}

test "IgnoreCache allocation-failure paths fall back without leaking" {
    // WHY two fixtures: a file-level rule makes buildRuleFacts early-return
    // with zero allocations (covers grow/dupe/put failure points); a
    // line-level rule allocates in facts.lines.put — the only sweep that
    // reaches the build-failure unwind. Alloc sequence per iteration (zig
    // 0.16.0): outer grow, file dupe, rule dupe, inner put (query A); file
    // dupe, rule dupe, lines.put == fail_index 6 (query B), inner put.
    const file_level =
        \\const a = foo() catch {}; // ephor:ignore ZA201
        \\const b = bar() catch {};
        \\// ephor:ignore-file ZC101
        \\const c = baz() catch {};
    ;
    const line_level = "const a = foo() catch {}; // ephor:ignore ZA201\n" ++
        "const b = bar() catch {};\n";

    // Measure the cold-run allocation count so the sweep covers every induced
    // failure point (plus one no-failure run) without hardcoding std internals.
    var probe = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var probe_cache = IgnoreCache.init(probe.allocator());
    _ = probe_cache.isSuppressed(file_level, "oom.zig", 4, "ZC101");
    _ = probe_cache.isSuppressed(line_level, "oom2.zig", 1, "ZA201");
    probe_cache.deinit();
    const total_allocs = probe.allocations;

    var fail_index: usize = 0;
    while (fail_index <= total_allocs) : (fail_index += 1) {
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
            .fail_index = fail_index,
        });
        var cache = IgnoreCache.init(failing.allocator());
        const got_file = cache.isSuppressed(file_level, "oom.zig", 4, "ZC101");
        const got_line = cache.isSuppressed(line_level, "oom2.zig", 1, "ZA201");
        cache.deinit();
        try std.testing.expectEqual(isInlineDisabled(file_level, 4, "ZC101"), got_file);
        try std.testing.expectEqual(isInlineDisabled(line_level, 1, "ZA201"), got_line);
        // Every successful allocation must be released by deinit at every
        // failure point — byte balance is the leak proof.
        try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
    }
}

test "checkSilentCatch detects catch {}" {
    // Basic catch {} should be detected
    const issue = checkSilentCatch(.{
        .t = "foo() catch {}",
        .path = "test.zig",
        .line = 1,
        .func_name = "processData",
    });
    try std.testing.expect(issue != null);
    try std.testing.expectEqualStrings("ZA201", issue.?.rule);
}

test "checkSilentCatch skips defer context" {
    // Same-line defer should not be detected
    const issue = checkSilentCatch(.{
        .t = "defer foo() catch {}",
        .path = "test.zig",
        .line = 1,
        .func_name = "init",
    });
    try std.testing.expect(issue == null);
}

test "checkSilentCatch skips mid-line defer context (EPH-I0426)" {
    // Band B06 F20: the defer suppression was line-start-only, so
    // `x: { defer f() catch {}; }` fired even though the block-form
    // tracker suppresses the equivalent multi-line defer. The suppression
    // now uses the same code-position detection as the ZA206 has-defer
    // tracker (EPH-I0416).
    const issue = checkSilentCatch(.{
        .t = "x: { defer f() catch {}; }",
        .path = "test.zig",
        .line = 1,
        .func_name = "init",
    });
    try std.testing.expect(issue == null);
}

test "checkSilentCatch mid-line defer suppression is string- and comment-aware (EPH-I0426)" {
    // A defer in a string or in comment prose never suppresses a real
    // catch on the same line.
    const in_string = checkSilentCatch(.{
        .t = "const s = \"defer \"; foo() catch {};",
        .path = "test.zig",
        .line = 1,
        .func_name = "init",
    });
    try std.testing.expect(in_string != null);
    const in_comment = checkSilentCatch(.{
        .t = "foo() catch {}; // defer cleanup",
        .path = "test.zig",
        .line = 1,
        .func_name = "init",
    });
    try std.testing.expect(in_comment != null);
}

test "analyzeErrors detects silent catch (ZA201)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();

    const test_content =
        \\fn bad_silent_catch() void {
        \\    foo() catch {};
        \\}
        \\fn foo() !void {}
    ;

    const analysis = try createTestFileAnalysis(allocator, "test_silent_catch.zig", test_content);
    try graph.files.put(analysis.path, analysis);

    var issues = try analyzeErrors(allocator, &graph);
    defer deinitIssues(&issues, allocator);

    // Should detect the silent catch, as a warning (README documents ZA201 as
    // warning severity)
    var found_za201 = false;
    for (issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_SILENT_CATCH)) {
            try std.testing.expect(issue.severity == .warning);
            found_za201 = true;
            break;
        }
    }
    try std.testing.expect(found_za201);
}

test "analyzeCFGDeferCoverage detects defer only in conditional branch" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Test content: defer only in if-true branch
    const test_content =
        \\fn bad_conditional_defer(allocator: std.mem.Allocator, condition: bool) void {
        \\    const data = allocator.alloc(u8, 100) catch return;
        \\    if (condition) {
        \\        defer allocator.free(data);
        \\        process(data);
        \\    }
        \\}
    ;

    // Build CFG and analyze
    var lines_list = std.ArrayListUnmanaged([]const u8).empty;
    defer lines_list.deinit(allocator);

    var line_iter = mem.splitScalar(u8, test_content, '\n');
    while (line_iter.next()) |line| {
        try lines_list.append(allocator, line);
    }

    var cfg = try buildCFG(allocator, "bad_conditional_defer", 1, lines_list.items);
    defer cfg.deinit();

    var issues = try analyzeCFGDeferCoverage(.{
        .allocator = allocator,
        .cfg = &cfg,
        .body = .{
            .lines = lines_list.items,
            .func_line = 1,
            .file_path = "test_conditional.zig",
        },
        .file_no_free_fields = null,
    });
    defer deinitIssues(&issues, allocator);

    // Should detect that defer is not on all paths
    var found_issue = false;
    for (issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_ALLOC_NO_DEFER)) {
            found_issue = true;
            break;
        }
    }
    try std.testing.expect(found_issue);
}

