test "definite-assignment worklist drains within the 2B+1 cap (EPH-I0335, EPH-I1003)" {
    const allocator = std.testing.allocator;
    // A small branchy function. The queue-driven fixpoint must visit
    // each block at most twice (initial plus one re-visit per state
    // flip): the sweep form it replaced made up to 2B+1 full passes
    // over every edge. Pre-fix, a chain-shaped CFG of B blocks paid
    // O(B^2) visits; the drain is the hermetic pin.
    //
    // The loop condition caps visits at 2B+1, so a <= assertion can
    // never fail (EPH-I1003): the cap exits only with visits == 2B+1
    // and returns that exact value. The strict form discriminates the
    // two exits. It holds only when the queue drained, and fails only
    // when the cap truncated the run — the F-13 under-approximation,
    // where a read may report where a longer run would prove coverage.
    // The monotone bound says the drain always comes first on the
    // shapes the CFG builder produces (loop-back preds are excluded).
    const lines = [_][]const u8{
        "fn f(a: bool) !void {",
        "    if (a) {",
        "        try g();",
        "    }",
        "    try h();",
        "}",
    };
    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();
    var nb = try buildBlockNeighbors(allocator, &cfg);
    defer nb.deinit(allocator);
    const num_blocks = cfg.blocks.items.len;
    const gen = try allocator.alloc(bool, num_blocks);
    defer allocator.free(gen);
    @memset(gen, false);
    const def_entry = try allocator.alloc(bool, num_blocks);
    defer allocator.free(def_entry);
    const def_exit = try allocator.alloc(bool, num_blocks);
    defer allocator.free(def_exit);
    @memset(def_entry, false);
    @memset(def_exit, false);
    const queue = try allocator.alloc(usize, num_blocks *| 2 +| 1);
    defer allocator.free(queue);
    const in_queue = try allocator.alloc(bool, num_blocks);
    defer allocator.free(in_queue);
    @memset(in_queue, false);
    const visits = runDefiniteAssignmentWorklist(&nb, .{
        .gen = gen,
        .def_entry = def_entry,
        .def_exit = def_exit,
        .num_blocks = num_blocks,
    }, queue, in_queue);
    try std.testing.expect(visits < num_blocks *| 2 +| 1);
}

test "definite-assignment converges on a 10k-line adversarial function (EPH-I0335)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // 1000 undefined vars, each read inside four nested same-condition
    // ifs — the guard-walk and correlated-guard scans' worst shape.
    // Pre-fix, the 11k-line input hung the analyzer past five minutes
    // (the O(n^3) per-var scans and the O(B^2 * E) worklist); the
    // bounded scans and the queue worklist finish the 11k shape in
    // 10.7 s (A/B measured at dispatch on the ReleaseSafe binary). The
    // verdicts stay exact: every uncovered read still reports.
    var body: std.ArrayListUnmanaged([]const u8) = .empty;
    var owned: std.ArrayListUnmanaged([]const u8) = .empty;
    try body.append(allocator, "fn adversarial() void {");
    try body.append(allocator, "    var g: ?u32 = null;");
    var i: usize = 0;
    while (i < 1000) : (i += 1) {
        const decl = try std.fmt.allocPrint(
            allocator,
            "    var v{d}: u32 = undefined;",
            .{i},
        );
        try owned.append(allocator, decl);
        try body.append(allocator, decl);
        var d: usize = 0;
        while (d < 4) : (d += 1) {
            try body.append(allocator, "    if (g != null) {");
        }
        const read = try std.fmt.allocPrint(
            allocator,
            "    const r{d} = v{d};",
            .{ i, i },
        );
        try owned.append(allocator, read);
        try body.append(allocator, read);
        const fill = try std.fmt.allocPrint(
            allocator,
            "    if (r{d} == 0) {{ v{d} = 1; }}",
            .{ i, i },
        );
        try owned.append(allocator, fill);
        try body.append(allocator, fill);
        d = 0;
        while (d < 4) : (d += 1) {
            try body.append(allocator, "    }");
        }
    }
    try body.append(allocator, "}");
    const lines = try body.toOwnedSlice(allocator);
    defer {
        for (owned.items) |s| allocator.free(s);
        owned.deinit(allocator);
        allocator.free(lines);
    }

    var cfg = try buildCFG(allocator, "adversarial", 1, lines);
    defer cfg.deinit();

    var def_issues = try analyzeDefiniteAssignment(allocator, &cfg, lines, 1);
    defer def_issues.deinit();

    try std.testing.expectEqual(@as(usize, 1000), def_issues.count());
}

test "analyzeDefiniteAssignment: OOM mid-run unwinds both maps (EPH-I0337)" {
    const allocator = std.testing.allocator;
    const lines = [_][]const u8{
        "fn f() u32 {",
        "    var x: u32 = undefined;",
        "    var y: u32 = undefined;",
        "    return x + y;",
        "}",
    };
    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // Measure the cold-run allocation count so the sweep covers every
    // induced failure point (plus one no-failure run).
    var probe = std.testing.FailingAllocator.init(allocator, .{});
    {
        var def_issues = try analyzeDefiniteAssignment(probe.allocator(), &cfg, &lines, 1);
        def_issues.deinit();
    }
    const total_allocs = probe.allocations;

    var fail_index: usize = 0;
    while (fail_index <= total_allocs) : (fail_index += 1) {
        var failing = std.testing.FailingAllocator.init(allocator, .{
            .fail_index = fail_index,
        });
        var issues = analyzeDefiniteAssignment(failing.allocator(), &cfg, &lines, 1) catch |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
            // Byte balance at the failure point is the leak proof: the
            // errdefers free the issues map and the undef-vars map on
            // the OOM path (band-B01b F-11).
            try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
            continue;
        };
        issues.deinit();
        try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
    }
}

// ============================================================================
// CFG expression-brace guard tests (EPH-I0079 A1)
// ============================================================================

fn cfgHasEdge(cfg: *const ControlFlowGraph, from: usize, to: usize, kind: EdgeKind) bool {
    for (cfg.edges.items) |e| {
        if (e.from == from and e.to == to and e.kind == kind) return true;
    }
    return false;
}

test "buildCFG: struct literal close does not pop if block" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(cond: bool) void {", // 1
        "    var x: u32 = 0;", // 2
        "    if (cond) {", // 3
        "        const cfg = C{", // 4
        "            .a = 1,", // 5
        "        };", // 6
        "        x = 1;", // 7
        "    }", // 8
        "}", // 9
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // Line 7 must stay in the if-true block, not fall through to the merge
    const if_block = findBlockForLine(&cfg, 4);
    try std.testing.expect(if_block != null);
    try std.testing.expectEqual(if_block, findBlockForLine(&cfg, 7));
}

test "buildCFG: call-arg close does not pop if block" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(cond: bool) void {", // 1
        "    var x: u32 = 0;", // 2
        "    if (cond) {", // 3
        "        foo(", // 4
        "            .{", // 5
        "                .a = 1,", // 6
        "            },", // 7: exact `},` line — the expression-close bug trigger
        "        );", // 8
        "        x = 1;", // 9
        "    }", // 10
        "}", // 11
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    const if_block = findBlockForLine(&cfg, 4);
    try std.testing.expect(if_block != null);
    try std.testing.expectEqual(if_block, findBlockForLine(&cfg, 9));
}

test "buildCFG: switch arm block close does not pop switch entry" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(x: u8) void {", // 1
        "    switch (x) {", // 2
        "        .a => {", // 3
        "            g();", // 4
        "        },", // 5
        "        .b => {", // 6
        "            h();", // 7
        "        },", // 8
        "    }", // 9
        "}", // 10
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // Both arms must branch from the switch header block; the first arm's
    // `},` close must not pop the switch entry before arm .b is wired up.
    const header = findBlockForLine(&cfg, 2) orelse return error.TestUnexpectedResult;
    const arm_a = findBlockForLine(&cfg, 4) orelse return error.TestUnexpectedResult;
    const arm_b = findBlockForLine(&cfg, 7) orelse return error.TestUnexpectedResult;
    try std.testing.expect(cfgHasEdge(&cfg, header, arm_a, .branch_true));
    try std.testing.expect(cfgHasEdge(&cfg, header, arm_b, .branch_true));
}

test "buildCFG: int, range, discard, and string prongs open arm blocks (EPH-I0679)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(x: u8, s: []const u8) void {", // 1
        "    switch (x) {", // 2
        "        1 => {", // 3
        "            g();", // 4
        "        },", // 5
        "        0...9 => {", // 6
        "            h();", // 7
        "        },", // 8
        "        _ => {", // 9
        "            i();", // 10
        "        },", // 11
        "    }", // 12
        "    switch (s) {", // 13
        "        \"a\" => {", // 14
        "            j();", // 15
        "        },", // 16
        "        else => {", // 17
        "            k();", // 18
        "        },", // 19
        "    }", // 20
        "}", // 21
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // EPH-I0679: every prong form branches from its switch header. Before
    // the fix these bodies attributed to the header (or the previous arm),
    // whose exit bit is unconditional.
    const int_header = findBlockForLine(&cfg, 2) orelse return error.TestUnexpectedResult;
    const str_header = findBlockForLine(&cfg, 13) orelse return error.TestUnexpectedResult;
    for ([_]usize{ 4, 7, 10 }) |body_line| {
        const arm = findBlockForLine(&cfg, body_line) orelse
            return error.TestUnexpectedResult;
        try std.testing.expect(cfgHasEdge(&cfg, int_header, arm, .branch_true));
    }
    for ([_]usize{ 15, 18 }) |body_line| {
        const arm = findBlockForLine(&cfg, body_line) orelse
            return error.TestUnexpectedResult;
        try std.testing.expect(cfgHasEdge(&cfg, str_header, arm, .branch_true));
    }
}

test "buildCFG: arrow text in a body string opens no phantom arm (EPH-I0679)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(x: u8) void {", // 1
        "    switch (x) {", // 2
        "        .a => {", // 3
        "            s = \"=>\";", // 4: string data, not a prong
        "        },", // 5
        "        .b => {", // 6
        "            g();", // 7
        "        },", // 8
        "    }", // 9
        "}", // 10
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // EPH-I0679 quote-mask guard: exactly two arms branch from the header.
    // An unmasked `=>` scan would read line 4 as a prong and open a third.
    const header = findBlockForLine(&cfg, 2) orelse return error.TestUnexpectedResult;
    var arm_count: usize = 0;
    for (cfg.edges.items) |e| {
        if (e.from == header and e.kind == .branch_true) arm_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 2), arm_count);
}

test "buildCFG: quoted braces do not corrupt depth; comment close counts" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(cond: bool) void {", // 1
        "    var x: u32 = 0;", // 2
        "    if (cond) {", // 3
        "        const s = \"{\";", // 4
        "        const c = '{';", // 5
        "        x = 1;", // 6
        "    } // trailing comment", // 7
        "    x = 2;", // 8
        "}", // 9
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    const if_block = findBlockForLine(&cfg, 4);
    try std.testing.expect(if_block != null);
    try std.testing.expectEqual(if_block, findBlockForLine(&cfg, 6));
    // `} // comment` is comment-aware now: it pops the if block.
    const after = findBlockForLine(&cfg, 8);
    try std.testing.expect(after != null);
    try std.testing.expect(if_block.? != after.?);
}

test "buildCFG: multiline opener tail braces do not corrupt depth (EPH-I0671)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(cond: bool) void {", // 1
        "    if (cond) {", // 2
        "        const s = \\\\ }", // 3: the tail `}` is string data
        "        x = 1;", // 4
        "    }", // 5
        "    x = 2;", // 6
        "}", // 7
    };
    // No-string baseline: same line count, a plain statement in place of the
    // multiline string.
    const baseline = [_][]const u8{
        "fn f(cond: bool) void {", // 1
        "    if (cond) {", // 2
        "        const s = 0;", // 3
        "        x = 1;", // 4
        "    }", // 5
        "    x = 2;", // 6
        "}", // 7
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();
    var base_cfg = try buildCFG(allocator, "f", 1, &baseline);
    defer base_cfg.deinit();

    // The tail `}` must not close the if body early: line 4 stays in the
    // if-true block and the structure matches the no-string baseline.
    try std.testing.expectEqual(base_cfg.blocks.items.len, cfg.blocks.items.len);
    const if_block = findBlockForLine(&cfg, 4);
    try std.testing.expect(if_block != null);
    try std.testing.expectEqual(findBlockForLine(&base_cfg, 4), if_block);
    const after = findBlockForLine(&cfg, 6);
    try std.testing.expect(after != null);
    try std.testing.expect(if_block.? != after.?);
}

test "scanLineForStatementEnd stops at a multiline opener (EPH-I0751)" {
    var depth: usize = 0;
    var mode: QuoteMode = .none;
    // Target text: const s = \\ foo(); bar(); — the tail semicolons are
    // string data, so the statement continues on a later line.
    try std.testing.expect(scanLineForStatementEnd("const s = \\\\ foo(); bar();", 0, &depth, &mode) == null);
    try std.testing.expectEqual(@as(usize, 0), depth);
    // A real depth-0 semicolon still terminates the statement.
    depth = 0;
    mode = .none;
    try std.testing.expectEqual(@as(?usize, 6), scanLineForStatementEnd("foo();", 0, &depth, &mode));
}

test "scanLineForParenClose stops at a multiline opener (EPH-I0751)" {
    var depth: usize = 1;
    var mode: QuoteMode = .none;
    // Target text: a, \\ b); c); — the tail parens are string data, so the
    // group closes on a later line.
    try std.testing.expect(scanLineForParenClose("a, \\\\ b); c);", 0, &depth, &mode) == null);
    try std.testing.expectEqual(@as(usize, 1), depth);
    // A real close paren still balances the group.
    depth = 1;
    mode = .none;
    try std.testing.expectEqual(@as(?usize, 5), scanLineForParenClose("a, b);", 0, &depth, &mode));
}

test "ForLoopTracker.checkLoopEnd ignores braces in a multiline opener tail (EPH-I0751)" {
    // Target text: const s = \\ } — the tail `}` is string data and must
    // not close the loop.
    var tracker: ForLoopTracker = .{ .in_loop = true };
    tracker.checkLoopEnd("const s = \\\\ }", 0);
    try std.testing.expect(tracker.in_loop);
    // A real net-negative brace line still ends the loop.
    tracker.checkLoopEnd("}", 0);
    try std.testing.expect(!tracker.in_loop);
}

test "hasOnelineLoopClose classifies one-line loop shapes (EPH-I0785)" {
    // The probe line: the braces balance within the code portion.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { sum +%= buf[x]; }"));
    // A trailing comment does not reopen the close.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { foo(); } // done"));
    // A stray semicolon after the body still closes on the line.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { foo(); };"));
    // A brace inside a string literal is data, not the body close.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { s = \"}\"; }"));
    // Multi-line header: the body brace stays open.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| {"));
    // A comment hides the real close: the body continues on later lines.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| { foo(); // }"));
    // A nested trailing close still leaves the body open.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| { if (y) { foo(); }"));
    // A header anonymous struct with a brace-less body on later lines.
    try std.testing.expect(!hasOnelineLoopClose("for (o.{ 1, 2 }) |x|"));
    // A brace-less body that ends on the line completes the loop
    // (EPH-I0789).
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| foo();"));
    // The body closes mid-line. The extra `}` belongs to an outer block.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { foo(); } }"));
}

test "hasOnelineLoopClose closes brace-less and trailing-statement loops (EPH-I0789)" {
    // The probe shape: a brace-less body whose statement ends on the line.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| sum +%= buf[x];"));
    // A trailing statement after the balanced body sits outside the loop.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { foo(); } bar();"));
    // The else block after the balanced close sits outside the loop. Its
    // fills are not loop-carried.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { foo(); } else {"));
    // A nested brace-less loop completes on the line.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| for (ys) |y| foo();"));
    // A `;` inside a char literal is data. The final `;` ends the body.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| c = ';';"));
    // Call-argument braces stay out of the body balance.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| foo(.{ 1, 2 });"));
    // A bare header leaves the body to later lines: the multi-line
    // brace-less shape keeps the historical behavior.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x|"));
    // A body expression that continues past the line is not one-line.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| sum +%="));
    // A `;` in a multiline-string tail is string data, not the body end.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| s = \\\\x; y();"));
    // An unclosed call paren holds the body open past the line.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| foo(a,"));
}

test "computeBraceDepth ignores braces in a multiline opener tail (EPH-I0751)" {
    // Target text: const s = \\ } — the tail `}` is string data and must
    // not pay the caller's carried depth.
    try std.testing.expectEqual(@as(usize, 1), computeBraceDepth("const s = \\\\ }", 1));
    // A real close brace still pays it.
    try std.testing.expectEqual(@as(usize, 0), computeBraceDepth("}", 1));
}

test "trackBackwardBraces ignores braces in a multiline opener tail (EPH-I0751)" {
    // Target text: const s = \\ { — the tail `{` is string data and must
    // not read as an enclosing block opener.
    const r = trackBackwardBraces("const s = \\\\ {", 0);
    try std.testing.expectEqual(@as(usize, 0), r.depth);
    try std.testing.expect(!r.opens_enclosing_block);
    // A real unmatched open still opens an enclosing block.
    const real = trackBackwardBraces("{", 0);
    try std.testing.expect(real.opens_enclosing_block);
}

test "trackBracesWithZeroDetect ignores braces in a multiline opener tail (EPH-I0751)" {
    // Target text: const s = \\ } — the tail `}` is string data: no depth
    // change, no zero crossing.
    const r = trackBracesWithZeroDetect("const s = \\\\ }", 1, true);
    try std.testing.expectEqual(@as(usize, 1), r.depth);
    try std.testing.expect(!r.touched_zero);
    // A real close brace still touches zero.
    const real = trackBracesWithZeroDetect("}", 1, true);
    try std.testing.expect(real.touched_zero);
}

test "computeBraceDepth ignores braces in comments and strings (EPH-I0081)" {
    // A trailing-comment brace is data: it neither opens nor closes a
    // block. A real opener before the comment still counts, and a string
    // brace never counts.
    try std.testing.expectEqual(@as(usize, 0), computeBraceDepth("x = 1; // { }", 0));
    try std.testing.expectEqual(@as(usize, 1), computeBraceDepth("if (c) { // }", 0));
    try std.testing.expectEqual(@as(usize, 0), computeBraceDepth("const s = \"{\" // }", 0));
    try std.testing.expectEqual(@as(usize, 1), computeBraceDepth("if (c) { const s = \"}\"; // {", 0));
}

test "trackBracesWithZeroDetect ignores braces in comments (EPH-I0081)" {
    // A comment `}` must not close the chain branch and touch zero.
    const r = trackBracesWithZeroDetect("if (c) { // }", 0, false);
    try std.testing.expectEqual(@as(usize, 1), r.depth);
    try std.testing.expect(r.found_open);
    try std.testing.expect(!r.touched_zero);
}

test "braceDepthAt ignores braces in comments (EPH-I0081)" {
    // A comment `{` must not score the assignment position as depth 1:
    // the assign on `x = 1; // {` sits at depth 0.
    try std.testing.expectEqual(@as(usize, 0), braceDepthAt("x = 1; // {", 11, 0));
    try std.testing.expectEqual(@as(usize, 1), braceDepthAt("if (c) { // }", 9, 0));
}

test "isIndirectlyInitialized ignores string braces in for-loop depth (EPH-I0081)" {
    // A `"}"` value inside the loop body must not close the loop depth
    // early: the later indexed fill stays inside the loop.
    const lines = [_][]const u8{
        "for (items) |i| {",
        "    const msg = \"}\";",
        "    buf[i] = 1;",
        "}",
    };
    try std.testing.expect(isIndirectlyInitialized(&lines, "buf"));
}

test "ComptimeState.update ignores braces in string literals (EPH-I0081)" {
    // A `"}"` value inside a comptime block is data: it must not close
    // the block scope early, and the real closing brace still pays.
    var st = ComptimeState{};
    st.update("comptime {");
    st.update("const s = \"}\";");
    try std.testing.expectEqual(@as(usize, 1), st.depth);
    st.update("}");
    try std.testing.expectEqual(@as(usize, 0), st.depth);
}

test "braceDepthFrom ignores braces in a multiline opener tail (EPH-I0751)" {
    // Target text: const s = \\ } — the tail `}` is string data and must
    // not pay the caller's carried depth.
    try std.testing.expectEqual(@as(usize, 1), braceDepthFrom("const s = \\\\ }", 0, 1));
    // A real close brace still pays it.
    try std.testing.expectEqual(@as(usize, 0), braceDepthFrom("}", 0, 1));
}

test "lineOpensErrorBlock ignores error-open text in a multiline opener tail (EPH-I0751)" {
    // Target text: const s = \\ error{NotReal} — the tail is string data.
    try std.testing.expect(!lineOpensErrorBlock("const s = \\\\ error{NotReal}"));
    // A real error-set open still counts.
    try std.testing.expect(lineOpensErrorBlock("const E = error{Real};"));
}

test "lineOpensErrorBlock ignores a backslash pair inside a char literal (EPH-I0751)" {
    // Target text: const sep = '\\'; const E = error{Real}; — the `'\\'`
    // char data is not a multiline opener, so the real error-set open counts.
