test "nextCallSite ignores call-shaped text in a multiline opener tail (EPH-I0751)" {
    // Target text: const s = \\ foo() — the tail call is string data.
    try std.testing.expect(nextCallSite("const s = \\\\ foo()", 0) == null);
    // A real call still resolves.
    const site = nextCallSite("const x = foo()", 0);
    try std.testing.expect(site != null);
    try std.testing.expectEqual(@as(usize, 10), site.?.start);
}

test "nextCallSite and quotedCallSite accept whitespace before the paren (EPH-I0433)" {
    // `foo ()` is a call of foo: Zig allows whitespace between the target
    // and its `(`. The site's name range must exclude the whitespace, or
    // name indexes carry a trailing space.
    const plain = nextCallSite("const x = foo ()", 0) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 10), plain.start);
    try std.testing.expectEqual(@as(usize, 13), plain.name_end);
    try std.testing.expectEqual(@as(usize, 14), plain.open_paren);
    try std.testing.expect(mem.eql(u8, callSiteName("const x = foo ()", plain), "foo"));

    const quoted = nextCallSite("const x = @\"my fn\" ()", 0) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 10), quoted.start);
    try std.testing.expectEqual(@as(usize, 18), quoted.name_end);
    try std.testing.expectEqual(@as(usize, 19), quoted.open_paren);
    try std.testing.expect(mem.eql(u8, callSiteName("const x = @\"my fn\" ()", quoted), "my fn"));

    // A run with no paren after the whitespace is still not a call.
    try std.testing.expect(nextCallSite("const x = foo ", 0) == null);
}

test "char-literal contents are not references or try-calls (EPH-I0432)" {
    // A 1-char candidate inside a char literal is literal data, not a
    // value reference; a `(` inside a char literal is not a call opener.
    try std.testing.expect(!hasIdentRef("const c = 'f';", "f"));
    try std.testing.expect(hasIdentRef("const f = 1;", "f"));
    try std.testing.expect(!hasCallBeforeSemicolon(" x == '(';"));
    try std.testing.expect(!hasCallBeforeSemicolon(" x == ';';"));
    try std.testing.expect(hasCallBeforeSemicolon(" foo(x)"));
}

test "buildCFG: Allman if brace on next line pops correctly" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(a: bool) void {", // 1
        "    if (a)", // 2
        "    {", // 3
        "        g();", // 4
        "    }", // 5
        "    h();", // 6
        "}", // 7
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    const if_block = findBlockForLine(&cfg, 4);
    const after = findBlockForLine(&cfg, 6);
    try std.testing.expect(if_block != null);
    try std.testing.expect(after != null);
    try std.testing.expect(if_block.? != after.?);
}

test "isErrorSetOpen accepts whitespace before the brace (EPH-I0470)" {
    // `error { A }` is valid Zig: the brace at index 6 opens the set, not
    // the function body.
    try std.testing.expect(isErrorSetOpen("error { A }", 6));
    // The adjacent form keeps working.
    try std.testing.expect(isErrorSetOpen("error{A}", 5));
    // A plain body brace is not an error-set open.
    try std.testing.expect(!isErrorSetOpen("fn f() {", 7));
    // `!error{...}` keeps working: `!` is not an identifier byte.
    try std.testing.expect(isErrorSetOpen("!error{", 6));
    // A spaced error set in a signature keeps working; the body brace
    // opens later (EPH-I0470).
    try std.testing.expect(isErrorSetOpen("fn f() error {", 13));
    // `myerror {` is a return type: the brace opens the body, not an
    // error set (EPH-I0885). The spaced form is the regression shape.
    try std.testing.expect(!isErrorSetOpen("fn f() myerror {", 15));
    // The adjacent `myerror{` shape is rejected the same way (EPH-I0885).
    try std.testing.expect(!isErrorSetOpen("myerror{", 7));
}

test "scanCFGSignatureLine: spaced error set is not the body brace (EPH-I0470)" {
    // The `{` of `error { OutOfMemory }` must count as a signature
    // container; the body opens only at the real `{` after the return type.
    var state = CFGState{};
    const pos = scanCFGSignatureLine("fn f() error { OutOfMemory } void {", &state);
    try std.testing.expect(state.body_started);
    try std.testing.expectEqual(@as(usize, 1), state.brace_depth);
    try std.testing.expectEqual(@as(usize, 0), state.sig_container_depth);
    try std.testing.expectEqual(@as(usize, 35), pos);
}

test "scanCFGSignatureLine masks string-literal parens (EPH-I0887)" {
    // A `)` inside a string-literal default is data, not syntax: the
    // paren count must stay balanced so the body `{` still opens at its
    // real position (EPH-I0887, the EPH-I0465 sibling masking).
    var state = CFGState{};
    const pos = scanCFGSignatureLine("fn f(a: []const u8 = \")\") void {", &state);
    try std.testing.expect(state.body_started);
    try std.testing.expectEqual(@as(usize, 1), state.brace_depth);
    try std.testing.expectEqual(@as(usize, 32), pos);
}

test "scanCFGSignatureLine ignores comment parens (EPH-I0887)" {
    // A comment `)` on a pre-body line is data: it must not close the
    // carried paren count early, or the body `{` reads as a signature
    // container and the CFG extraction never starts the body.
    var state = CFGState{};
    _ = scanCFGSignatureLine("fn f(a: usize) void // )", &state);
    const pos = scanCFGSignatureLine("{", &state);
    try std.testing.expect(state.body_started);
    try std.testing.expectEqual(@as(usize, 1), pos);
    try std.testing.expectEqual(@as(isize, 0), state.paren_depth);
}

test "scanCFGSignatureLine carries a continued string default (EPH-I0887)" {
    // A `\`+newline continuation keeps the string-literal default open
    // on the next signature line: the `)` and the body `{` after the
    // closing quote are syntax, not string data (EPH-I0887).
    var state = CFGState{};
    _ = scanCFGSignatureLine("fn f(a: []const u8 = \"foo \\", &state);
    try std.testing.expect(!state.body_started);
    const pos = scanCFGSignatureLine("    bar\") void {", &state);
    try std.testing.expect(state.body_started);
    try std.testing.expectEqual(@as(isize, 0), state.paren_depth);
    try std.testing.expectEqual(@as(usize, 1), state.brace_depth);
    try std.testing.expectEqual(@as(usize, 16), pos);
}

test "detectCFGFuncStart: a closed string before fn does not hide it (EPH-I0471)" {
    var state = CFGState{};
    // The return value reports a NESTED fn; the detection itself shows in
    // the state.
    const was_in_func = detectCFGFuncStart("const s = \"x\"; fn real() void {", &state, 1);
    try std.testing.expect(!was_in_func);
    try std.testing.expect(state.in_func);
    try std.testing.expectEqualStrings("real", state.func_name);
}

test "detectCFGFuncStart: an open string at fn_pos still rejects (EPH-I0471)" {
    var state = CFGState{};
    try std.testing.expect(!detectCFGFuncStart("const s = \"fn fake() void {", &state, 1));
    try std.testing.expect(!state.in_func);
}

test "detectCFGFuncStart: a string containing // does not hide fn (EPH-I0471)" {
    // The `//` is string data, not a comment start: the fn after the closed
