        "            if (cond) {", // 4
        "                v = 1;", // 5
        "            }", // 6: closes the if, not the arm's expression brace
        "            v += 1;", // 7: must be past the if (its merge), not if-true
        "        },", // 8
        "        else => {},", // 9
        "    }", // 10
        "}", // 11
    };

