    try std.testing.expectEqual(findBlockForLine(&cfg, 12), switch_merge);
    try std.testing.expect(cfgHasEdge(&cfg, arm_a, loop_merge, .break_jump));
    try std.testing.expect(!cfgHasEdge(&cfg, arm_a, switch_merge, .sequential));
