test "buildCFG: brace-less break body equals the braced form" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // break/continue are not CFG-modeled in either form (dispatchPattern
    // no-ops them, EPH-I0094): parity means identical plain-body structure.
    const bare = [_][]const u8{
        "fn f(a: bool, b: bool) void {",
        "    while (a) {",
        "        if (b) break;",
        "        x = 1;",
        "    }",
        "}",
    };
    const braced = [_][]const u8{
        "fn f(a: bool, b: bool) void {",
        "    while (a) {",
        "        if (b) { break; }",
        "        x = 1;",
        "    }",
        "}",
    };

    var cfg_bare = try buildCFG(allocator, "f", 1, &bare);
    defer cfg_bare.deinit();
    var cfg_braced = try buildCFG(allocator, "f", 1, &braced);
    defer cfg_braced.deinit();

    try std.testing.expectEqual(cfg_braced.blocks.items.len, cfg_bare.blocks.items.len);
    try std.testing.expect(cfgEdgesMatch(&cfg_bare, &cfg_braced));
}

test "buildCFG: two returns in one block append one exit id (EPH-I0325)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Both return lines sit in the same if body; the exit list must hold
    // the block id once (band-B01a F9). Consumers scan for membership,
    // so the duplicate was tolerated — the dedup keeps the list honest
    // for length-based consumers.
    const lines = [_][]const u8{
        "fn f(a: bool) !void {",
        "    if (a) {",
        "        return error.A;",
        "        return error.B;",
        "    }",
        "    return;",
        "}",
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    var count: usize = 0;
    for (cfg.exit_blocks.items) |exit_bid| {
        if (exit_bid == cfg.blocks.items.len - 2) count += 1;
    }
    // The if body is the second-to-last block: the last block is the
    // if's false-block merge, which handleBranch creates at open time;
    // buildCFG adds no block at fn close. Both returns live there.
    try std.testing.expectEqual(@as(usize, 1), count);
}

