    // EPH-I0098: `foo.x = 1` assigns a field of foo, not local x — the
    // null-guard correlation must not count it as an x assignment.
    const content =
        \\fn nullGuardFieldAssign(cond: bool) u32 {
        \\    var guard: ?u32 = null;
        \\    var x: u32 = undefined;
        \\    if (cond) {
        \\        guard = 1;
        \\        foo.x = 1;
        \\    }
        \\    if (guard) |_| {
        \\        return x;
        \\    }
        \\    return 0;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_nullguard_field.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        1,
        countRuleIssues(run.issues.items, "da_nullguard_field.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

test "ZA607: null-guard correlation keeps same-line second-occurrence assignment" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // EPH-I0098: the correlation's assignment search must scan every
    // same-line occurrence — the leading-dot `foo.x` is a field of another
    // var (neither a read nor an assignment of local x), and the genuine
    // `x = 2` follows it on the same line.
    // EPH-I0080: the original first occurrence `use(x)` was itself a genuine
    // read of x BEFORE the same-line assignment — line-order-aware gen now
    // reports that shape (see "same-line read before assignment"), so this
    // test uses a non-read first occurrence instead. The occurrence loop
    // visits every same-line match, so an assignment after a
    // non-assignment occurrence still counts (EPH-I0331).
    const content =
        \\fn nullGuardSecondOccurrence(cond: bool) u32 {
        \\    var guard: ?u32 = null;
        \\    var x: u32 = undefined;
        \\    if (cond) {
        \\        guard = 1;
        \\        foo.x = 1; x = 2;
        \\    }
        \\    if (guard) |_| {
        \\        return x;
        \\    }
        \\    return 0;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_nullguard_second.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        0,
