        \\fn use(v: u32) void {
        \\    _ = v;
        \\}
        \\fn switchOneLine(c: u32) void {
        \\    var x: u32 = undefined;
        \\    switch (c) { 1 => x = 1, else => {} }
        \\    use(x);
        \\}
    ;
