test "analyzeNaming: quoted identifiers are checked as their inner name (EPH-I0467)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();

    const code =
        \\fn @"quoted_bad"() void {}
        \\const @"quotedBadConst" = 1;
        \\var @"quotedBadVar": u32 = 0;
        \\fn @"goodName"() void {}
        \\const @"good_const" = 1;
        \\var @"good_var": u32 = 0;
        \\const @"*i32" = 4;
        \\const @"active-surface" = 1;
        \\pub const @"error" = struct {};
        \\extern const kTISPropertyLocalizedName: *CFString;
    ;
    const analysis = try createTestFileAnalysis(allocator, "test_quoted.zig", code);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, "test_quoted.zig"), {});

    var issues = try analyzeNaming(allocator, &graph, .title_case);
    defer deinitIssues(&issues, allocator);

    // The quoted form is a legal spelling of the same identifier, so the
    // convention checks the inner text; conforming inner names stay silent.
    // Quoted names with no unquoted spelling (`@"*i32"`, `@"active-surface"`,
    // `@"error"`) have no convention to enforce, and extern consts are
    // ABI-fixed — the documented exemptions (EPH-I0467).
    try std.testing.expectEqual(@as(usize, 3), issues.items.len);
    try std.testing.expectEqualStrings(
        "function 'quoted_bad' should be camelCase",
        issues.items[0].message,
    );
    try std.testing.expectEqualStrings(
        "constant 'quotedBadConst' should be snake_case",
        issues.items[1].message,
    );
    try std.testing.expectEqualStrings(
        "variable 'quotedBadVar' should be snake_case",
        issues.items[2].message,
    );
}

// ============================================================================
// ZA703 Closure-Wrapper / Type-Definition Classification Tests
// ============================================================================

test "isTypeDefinitionLine: real type defs detected (EPH-I0472)" {
    // The isTypeDefinition wrapper is deleted (EPH-I0472): each assertion
    // now pins the two primitives it composed — the line gate and the
    // closure-alias disambiguation — with the same inputs.
    const c1 = "const Foo = struct {};";
    try std.testing.expect(isTypeDefinitionLine(c1));
    try std.testing.expect(!isClosureFunctionAlias(c1, c1, 0));
    const c2 = "const Color = enum { red, green };";
    try std.testing.expect(isTypeDefinitionLine(c2));
    try std.testing.expect(!isClosureFunctionAlias(c2, c2, 0));
    const c3 = "const Tag = union { a: u32, b: u64 };";
    try std.testing.expect(isTypeDefinitionLine(c3));
    try std.testing.expect(!isClosureFunctionAlias(c3, c3, 0));
    const c4 = "const Bits = packed struct(u32) { a: u16, b: u16 };";
    try std.testing.expect(isTypeDefinitionLine(c4));
    try std.testing.expect(!isClosureFunctionAlias(c4, c4, 0));
}

test "isTypeDefinitionLine: single-line closure NOT a type def (EPH-I0472)" {
    const c = "const readBytes = struct { fn call() void {} }.call;";
    try std.testing.expect(isTypeDefinitionLine(c));
    try std.testing.expect(isClosureFunctionAlias(c, c, 0));
}

test "isTypeDefinitionLine: multi-line closure NOT a type def (EPH-I0472)" {
    const content =
        "const readBytes = struct {\n" ++
        "    fn call() void {}\n" ++
        "}.call;\n";
    // First line is what the analyzer trims and passes as `t`.
    const line = "const readBytes = struct {";
    try std.testing.expect(isTypeDefinitionLine(line));
    try std.testing.expect(isClosureFunctionAlias(line, content, 0));
}

test "isTypeDefinitionLine: nested braces inside closure body still resolved correctly (EPH-I0472)" {
    const content =
        "const wrap = struct {\n" ++
        "    fn call(a: u32) u32 {\n" ++
        "        if (a > 0) { return a; } else { return 0; }\n" ++
        "    }\n" ++
        "}.call;\n";
    const line = "const wrap = struct {";
    try std.testing.expect(isTypeDefinitionLine(line));
    try std.testing.expect(isClosureFunctionAlias(line, content, 0));
}

test "isTypeDefinitionLine: multi-line REAL type def still detected (EPH-I0472)" {
    const content =
        "const Foo = struct {\n" ++
        "    field: u32,\n" ++
        "};\n";
    const line = "const Foo = struct {";
    try std.testing.expect(isTypeDefinitionLine(line));
    try std.testing.expect(!isClosureFunctionAlias(line, content, 0));
}

test "isTypeDefinitionLine: array literal of anonymous struct not a type def (EPH-I0472)" {
    // `[_]struct { ... }{ ... }` has no space before `struct`, so the keyword
    // pattern ` struct` must NOT match.
    const c = "const keys = [_]struct { name: []const u8 }{ .{ .name = \"a\" } };";
    try std.testing.expect(!isTypeDefinitionLine(c));
    try std.testing.expect(!isClosureFunctionAlias(c, c, 0));
}

test "isClosureFunctionAlias: detects multi-line closure" {
    const content =
        "const readBytes = struct {\n" ++
        "    fn call() void {}\n" ++
        "}.call;\n";
    const line = "const readBytes = struct {";
    try std.testing.expect(isClosureFunctionAlias(line, content, 0));
}

test "isClosureFunctionAlias: rejects real type def" {
    const c = "const Foo = struct { x: u32 };";
    try std.testing.expect(!isClosureFunctionAlias(c, c, 0));
}

test "isTypeDefinitionLine: a closed string before the keyword does not mask it (EPH-I0474)" {
    // The old first-quote comparison masked any keyword behind a `"` opener,
    // even when the literal closed before the keyword: `"doc" ++ struct`
    // read as a value const, not a type def.
    const c = "const x = \"doc\" ++ struct { a: u32 };";
    try std.testing.expect(isTypeDefinitionLine(c));
}

test "isTypeDefinitionLine: a keyword inside a string stays masked (EPH-I0474)" {
    const c = "const x = \"doc struct\";";
    try std.testing.expect(!isTypeDefinitionLine(c));
}

test "isClosureFunctionAlias: a closed string before the keyword keeps alias detection (EPH-I0474)" {
    // Both scanners share the code-position keyword scan, so the closure
    // alias behind a string still reads as a function, not a type.
    const c = "const readBytes = \"doc\" ++ struct { fn call() void {} }.call;";
    try std.testing.expect(isTypeDefinitionLine(c));
    try std.testing.expect(isClosureFunctionAlias(c, c, 0));
}

// ============================================================================
// TypeContext / Return-Type-Aware Detection Tests
// ============================================================================

test "classifyReturnType identifies void" {
    try std.testing.expectEqual(ReturnKind.void_type, classifyReturnType("void"));
    try std.testing.expectEqual(ReturnKind.void_type, classifyReturnType("  void  "));
}

test "classifyReturnType identifies error unions" {
    try std.testing.expectEqual(ReturnKind.error_union, classifyReturnType("!void"));
    try std.testing.expectEqual(ReturnKind.error_union, classifyReturnType("!u32"));
    try std.testing.expectEqual(ReturnKind.error_union, classifyReturnType("anyerror!T"));
    try std.testing.expectEqual(ReturnKind.error_union, classifyReturnType("Error!void"));
}

test "classifyReturnType identifies optionals" {
    try std.testing.expectEqual(ReturnKind.optional, classifyReturnType("?u32"));
    try std.testing.expectEqual(ReturnKind.optional, classifyReturnType("?T"));
}

test "classifyReturnType identifies noreturn" {
    try std.testing.expectEqual(ReturnKind.noreturn_type, classifyReturnType("noreturn"));
}

test "classifyReturnType identifies values" {
    try std.testing.expectEqual(ReturnKind.value, classifyReturnType("u32"));
    try std.testing.expectEqual(ReturnKind.value, classifyReturnType("Response"));
    try std.testing.expectEqual(ReturnKind.value, classifyReturnType("bool"));
}

test "classifyReturnType returns unknown for empty" {
    try std.testing.expectEqual(ReturnKind.unknown, classifyReturnType(""));
    try std.testing.expectEqual(ReturnKind.unknown, classifyReturnType("   "));
}

test "extractFnReturnType parses simple signatures" {
    const r1 = extractFnReturnType("fn foo() void {");
    try std.testing.expect(r1 != null);
    try std.testing.expectEqualStrings("void", r1.?);

    const r2 = extractFnReturnType("pub fn bar(x: u32) !void {");
    try std.testing.expect(r2 != null);
    try std.testing.expectEqualStrings("!void", r2.?);

    const r3 = extractFnReturnType("fn baz(self: *Self) u32 {");
    try std.testing.expect(r3 != null);
    try std.testing.expectEqualStrings("u32", r3.?);
}

test "extractFnReturnType handles nested parens" {
    const r = extractFnReturnType("fn foo(cb: fn(u32) void, x: u32) !void {");
    try std.testing.expect(r != null);
    try std.testing.expectEqualStrings("!void", r.?);
}

test "extractSelfTypeName extracts pointer self types" {
    const t1 = extractSelfTypeName("fn foo(self: *MyStruct) void {");
    try std.testing.expect(t1 != null);
    try std.testing.expectEqualStrings("MyStruct", t1.?);

    const t2 = extractSelfTypeName("fn foo(self: *const MyStruct) void {");
    try std.testing.expect(t2 != null);
    try std.testing.expectEqualStrings("MyStruct", t2.?);

    const t3 = extractSelfTypeName("fn foo(x: u32) void {");
    try std.testing.expect(t3 == null);
}

test "extractFnName extracts function names" {
    try std.testing.expectEqualStrings("foo", extractFnName("fn foo() void {").?);
    try std.testing.expectEqualStrings("bar", extractFnName("pub fn bar(x: u32) !void {").?);
    try std.testing.expect(extractFnName("const x = 42;") == null);
}

test "extractFnName masks fn inside strings and identifiers (EPH-I0975)" {
    // The raw `fn ` match read a string or an identifier as a function
    // declaration (the EPH-I0949 residual class).
    try std.testing.expect(extractFnName("const pat = \"fn (\";") == null);
    try std.testing.expect(extractFnName("my_fn (x);") == null);
}

test "extractFnReturnType masks fn ( inside strings (EPH-I0975)" {
    try std.testing.expect(extractFnReturnType("const pat = \"fn (\";") == null);
    try std.testing.expect(extractFnReturnType("my_fn (x);") == null);
    try std.testing.expectEqualStrings("!void", extractFnReturnType("pub fn bar(x: u32) !void {").?);
}

test "registerFnSignature guard masks fn ( in strings (EPH-I0975)" {
    var ctx = TypeContext.init();
    defer ctx.deinit(std.testing.allocator);
    // A string carrying `fn (` is not a signature: the guard rejects it
    // before any registration.
    try std.testing.expect(!try registerFnSignature(std.testing.allocator, "const pat = \"fn (\";", null, &ctx));
    // The real signature still registers.
    try std.testing.expect(try registerFnSignature(std.testing.allocator, "fn g() void {", null, &ctx));
}

test "extractFnName accepts quoted names (EPH-I0922)" {
    // The quoted-name arm findRealFnDef uses (EPH-I0442, pubFnNameAt):
    // `fn @"quoted"()` yields the inner content, the spelling a call
    // site shares. Malformed quotes and fn-pointer shapes stay null.
    try std.testing.expectEqualStrings(
        "weird-name",
        extractFnName("fn @\"weird-name\"() void {").?,
    );
    try std.testing.expectEqualStrings("a-b", extractFnName("pub fn @\"a-b\"(x: u32) !void {").?);
    try std.testing.expect(extractFnName("fn @\"unterminated() void {}") == null);
    try std.testing.expect(extractFnName("cb: *const fn () void,") == null);
}

test "extractVarTypeName extracts explicit type annotations" {
    const t1 = extractVarTypeName("var x: MyStruct = .{};");
    try std.testing.expect(t1 != null);
    try std.testing.expectEqualStrings("MyStruct", t1.?);
}

test "extractVarTypeName extracts TypeName.init patterns" {
    const t1 = extractVarTypeName("var list = ArrayList(u8).init(allocator);");
    // ArrayList starts with uppercase, followed by (, so type is "ArrayList"
    try std.testing.expect(t1 != null);
    try std.testing.expectEqualStrings("ArrayList", t1.?);
}

test "extractVarTypeName extracts struct literal patterns" {
    const t1 = extractVarTypeName("var state = ErrorAnalysisState{};");
    try std.testing.expect(t1 != null);
    try std.testing.expectEqualStrings("ErrorAnalysisState", t1.?);
}

test "extractVarTypeName returns null for non-type RHS" {
    try std.testing.expect(extractVarTypeName("var x = some_func();") == null);
    try std.testing.expect(extractVarTypeName("var x = 42;") == null);
}

test "extractVarTypeName falls through to RHS when annotation yields no ident" {
    const t1 = extractVarTypeName("var x: * = Foo.init();");
    try std.testing.expect(t1 != null);
    try std.testing.expectEqualStrings("Foo", t1.?);
}

test "extractVarTypeName skips pointer then optional markers" {
    const t1 = extractVarTypeName("var p: *?Widget = undefined;");
    try std.testing.expect(t1 != null);
    try std.testing.expectEqualStrings("Widget", t1.?);
}

test "extractVarTypeName skips pointer qualifiers in annotations" {
    try std.testing.expectEqualStrings("Q", extractVarTypeName("var z: *const Q = undefined;").?);
    try std.testing.expectEqualStrings("T", extractVarTypeName("var t: *volatile T = undefined;").?);
    try std.testing.expectEqualStrings("Q", extractVarTypeName("var q: ?*const Q = undefined;").?);
}

test "extractVarTypeName skips allowzero qualifier (EPH-I0071)" {
    // `*allowzero u8` used to yield the garbage key "allowzero"; the
    // qualifier must be skipped like `volatile ` (I0057 precedent).
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var z: *allowzero u8 = undefined;").?);
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var z: *allowzero const u8 = undefined;").?);
}

test "extractVarTypeName skips slice and array prefixes" {
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var s: []u8 = undefined;").?);
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var a: [4]u8 = undefined;").?);
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var m: [*c]u8 = undefined;").?);
}

test "extractVarTypeName skips align specs and compound qualifier chains" {
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var p: *align(4) u8 = undefined;").?);
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var p: *align(4) const u8 = undefined;").?);
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var p: [*c]const u8 = undefined;").?);
    // Pathological nested parens: simple )-scan must fall to A-null, not mis-skip
    try std.testing.expect(extractVarTypeName("var p: *align(@alignOf(u8)) u8 = undefined;") == null);
}

test "extractVarTypeName skips error-union prefixes" {
    try std.testing.expectEqualStrings("Foo", extractVarTypeName("var e: error{X}!Foo = undefined;").?);
    try std.testing.expectEqualStrings("Foo", extractVarTypeName("var e: anyerror!Foo = undefined;").?);
    try std.testing.expectEqualStrings("Foo", extractVarTypeName("var e: !Foo = undefined;").?);
}

test "extractVarTypeName qualified annotation does not block RHS inference" {
    const t1 = extractVarTypeName("var z: *const Q = Q.init();");
    try std.testing.expect(t1 != null);
    try std.testing.expectEqualStrings("Q", t1.?);
}

test "extractVarTypeName returns null for qualifier-only annotation" {
    try std.testing.expect(extractVarTypeName("var q: *const = undefined;") == null);
}

test "extractMethodCall extracts receiver and method" {
    const r1 = extractMethodCall("_ = list.clear()");
    try std.testing.expect(r1 != null);
    try std.testing.expectEqualStrings("list", r1.?.receiver);
    try std.testing.expectEqualStrings("clear", r1.?.method);

    const r2 = extractMethodCall("_ = logger.reset()");
    try std.testing.expect(r2 != null);
    try std.testing.expectEqualStrings("logger", r2.?.receiver);
    try std.testing.expectEqualStrings("reset", r2.?.method);
}

test "extractMethodCall returns null for non-method calls" {
    try std.testing.expect(extractMethodCall("_ = someFunction()") == null);
    try std.testing.expect(extractMethodCall("const x = 42;") == null);
}

