test "parseFileTypeContext registers quoted fn names (EPH-I0922)" {
    // FN-direction: extractFnName returned null for `fn @"quoted"()`, so
    // registerFnSignature consumed the line without a table entry. The
    // quoted name now registers under its inner content.
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const a = gpa.allocator();

    const content =
        \\fn @"never-fails"() !void {}
        \\fn @"plain"() void {}
    ;
    var ctx = try parseFileTypeContext(a, content);
    defer ctx.deinit(a);

    try std.testing.expectEqual(ReturnKind.error_union, ctx.function_returns.get("never-fails").?);
    try std.testing.expectEqual(ReturnKind.void_type, ctx.function_returns.get("plain").?);
}

test "parseFileTypeContext: string brace does not corrupt type scope (EPH-I0894)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const a = gpa.allocator();

    // The struct body line `const label = "}";` holds a string close
    // brace. Pre-fix the raw brace walk closed the struct scope at
    // that line, so the method below registered as a top-level function
    // and the struct_methods table lost it.
    const content =
        \\const S = struct {
        \\    const label = "}";
        \\    pub fn method(self: *S) void {
        \\    }
        \\};
    ;

    var ctx = try parseFileTypeContext(a, content);
    defer ctx.deinit(a);

    const methods = ctx.struct_methods.get("S");
    try std.testing.expect(methods != null);
    try std.testing.expectEqual(ReturnKind.void_type, methods.?.get("method").?);
}

