// ============================================================================
// ZA701 Tests — unbreakable string-literal exemption
// ============================================================================

test "visibleLengthExcludingStrings counts only quote characters of literals" {
    // 4 spaces + quote + 113 x's + quote + comma = 120 visible, 7 excluding
    const long_literal = "    \"" ++ "x" ** 113 ++ "\",";
    try std.testing.expectEqual(@as(usize, 120), calculateVisibleLength(long_literal));
    try std.testing.expectEqual(@as(usize, 7), visibleLengthExcludingStrings(long_literal));
    // Pure code line — nothing excluded
    const pure_code = "x" ** 120;
    try std.testing.expectEqual(@as(usize, 120), visibleLengthExcludingStrings(pure_code));
    // Escaped quote inside a literal must not terminate it
    try std.testing.expectEqual(
        @as(usize, 13),
        visibleLengthExcludingStrings("const s = \"a\\\"b\";"),
    );
}

test "visibleLengthExcludingStrings does not treat '\"' char literal as a string" {
    // The '"' char literal must not mask the rest of the line as string content
    const char_line =
        "if (c == '\"') return self.handleTheStringLiteral" ++
        "WithAnExcessivelyLongFunctionName(alpha, beta, gamma);";
    try std.testing.expect(calculateVisibleLength(char_line) > 100);
    try std.testing.expect(visibleLengthExcludingStrings(char_line) > 100);
    // Char literals count as ordinary code, whatever their form
    try std.testing.expectEqual(
        @as(usize, 14),
        visibleLengthExcludingStrings("const q = '\"';"),
    );
    try std.testing.expectEqual(
        @as(usize, 16),
        visibleLengthExcludingStrings("const nl = '\\n';"),
    );
    try std.testing.expectEqual(
        @as(usize, 16),
        visibleLengthExcludingStrings("const sq = '\\'';"),
    );
    // Apostrophe-like ' not part of a char literal is ordinary code too
    try std.testing.expectEqual(
        @as(usize, 13),
        visibleLengthExcludingStrings("// don't stop"),
    );
    // Real string overage adjacent to a char literal stays exempt
    const mixed = "    if (c == '\"') return \"" ++ "x" ** 100 ++ "\";";
    try std.testing.expect(calculateVisibleLength(mixed) > 100);
    try std.testing.expectEqual(@as(usize, 28), visibleLengthExcludingStrings(mixed));
}

test "ZA701 exempts lines over-length solely due to string literals" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();

    const long_literal = "    \"" ++ "x" ** 113 ++ "\",";
    const short_string_long_code = "x" ** 50 ++ " \"ab\" " ++ "y" ** 60;
    const pure_code = "x" ** 120;
    const char_literal_line =
        "if (c == '\"') return self.handleTheStringLiteral" ++
        "WithAnExcessivelyLongFunctionName(alpha, beta, gamma);";
    const mixed_char_and_string = "    if (c == '\"') return \"" ++ "x" ** 100 ++ "\";";
    const code = long_literal ++ "\n" ++
        short_string_long_code ++ "\n" ++
        pure_code ++ "\n" ++
        char_literal_line ++ "\n" ++
        mixed_char_and_string ++ "\n";

    const analysis = try createTestFileAnalysis(allocator, "test_long_lines.zig", code);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, "test_long_lines.zig"), {});

    var issues = try analyzeStyle(allocator, &graph, .{});
    defer deinitIssues(&issues, allocator);

    var flagged_lines: usize = 0;
    for (issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_LINE_TOO_LONG)) {
            // Lines 1 (unbreakable literal) and 5 (literal + char literal) are
            // exempt; lines 2, 3, and 4 (char literal masking) are not.
            try std.testing.expect(issue.line != 1 and issue.line != 5);
            flagged_lines += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 3), flagged_lines);
}

test "ZA701: multi-byte lines count codepoints, not bytes (EPH-I0248)" {
    // 60 CJK chars = 180 bytes; the byte model reported 182 columns.
    // The codepoint model counts 63 (the "// " prefix included).
    const cjk = "// " ++ "界" ** 60;
    try std.testing.expectEqual(@as(usize, 63), calculateVisibleLength(cjk));
    try std.testing.expectEqual(@as(usize, 63), visibleLengthExcludingStrings(cjk));
    // Emoji: 25 four-byte sequences = 100 bytes, 28 codepoints.
    const emoji = "// " ++ "🚀" ** 25;
    try std.testing.expectEqual(@as(usize, 28), calculateVisibleLength(emoji));
    // Tabs keep the 4-stop model with codepoint counts.
    const tabbed = "\t" ++ "界" ** 40;
    try std.testing.expectEqual(@as(usize, 44), calculateVisibleLength(tabbed));
}

test "ZA701: malformed clusters stay byte-counted, valid ones collapse (EPH-I0248)" {
    // \xE2ab is 3 bytes: 0xE2 plus two ASCII bytes that are not valid
    // continuations, so the cluster falls back to 3 single-byte counts.
    // 3 + 98 ASCII bytes = 101 columns, over the 100 limit (fires).
    const malformed = "\xE2ab" ++ "x" ** 98;
    try std.testing.expectEqual(@as(usize, 101), calculateVisibleLength(malformed));
    // Overlong \xE0\x80\x80: the first continuation (0x80) is below the
    // 0xA0 floor for 0xE0, so all three bytes count separately.
    const overlong = "\xE0\x80\x80" ++ "x" ** 98;
    try std.testing.expectEqual(@as(usize, 101), calculateVisibleLength(overlong));
    // A valid 3-byte cluster still collapses to one column.
    const valid = "†" ++ "x" ** 99;
    try std.testing.expectEqual(@as(usize, 100), calculateVisibleLength(valid));
}

test "ZA701: a long CJK comment line is silent, a long ASCII+CJK line fires (EPH-I0248)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();

    // 60 CJK chars: 180 bytes but 63 codepoints — silent under the
    // codepoint model, flagged under the byte model.
    const cjk_line = "// " ++ "界" ** 60;
    // 60 CJK chars plus 50 ASCII chars: 113 codepoints — still too long.
    const over_line = "// " ++ "界" ** 60 ++ " " ++ "x" ** 49;
    const code = cjk_line ++ "\n" ++ over_line ++ "\n";

    const analysis = try createTestFileAnalysis(allocator, "test_cjk_lines.zig", code);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, "test_cjk_lines.zig"), {});

    var issues = try analyzeStyle(allocator, &graph, .{});
    defer deinitIssues(&issues, allocator);

    var flagged_lines: usize = 0;
    for (issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_LINE_TOO_LONG)) {
            try std.testing.expectEqual(@as(usize, 2), issue.line);
            flagged_lines += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 1), flagged_lines);
}

test "isInsideTypeOf detects @TypeOf context" {
    try std.testing.expect(isInsideTypeOf("const T = @TypeOf(foo() catch unreachable);", 30, null));
    try std.testing.expect(!isInsideTypeOf("const x = foo() catch unreachable;", 22, null));
}

test "isInsideTypeOf detects multi-line @TypeOf with inner call spanning lines" {
    // Inner function call spans multiple lines, catch unreachable on the last
    const prev = [_][]const u8{
        "const ReceiptsHolder = @TypeOf(",
        "    block_fetcher.fetchBlockReceipts(",
    };
    const line = "        undefined, 0) catch unreachable,";
    const col = mem.indexOf(u8, line, "catch unreachable").?;
    try std.testing.expect(isInsideTypeOf(line, col, &prev));
    // No preceding context
    try std.testing.expect(!isInsideTypeOf(line, col, null));
}

test "isInsideTypeOf detects balanced-paren line inside @TypeOf" {
    // pipeline.zig pattern: current line has balanced parens but is inside @TypeOf
    const prev2 = [_][]const u8{
        "const ReceiptsHolder = @TypeOf(",
    };
    const line = "block_fetcher.fetchBlockReceipts(undefined, 0) catch unreachable,";
    const col = mem.indexOf(u8, line, "catch unreachable").?;
    try std.testing.expect(isInsideTypeOf(line, col, &prev2));
    // Same line but no @TypeOf wrapper — should NOT suppress
    const prev3 = [_][]const u8{
        "const result = someFunction(",
    };
    try std.testing.expect(!isInsideTypeOf(line, col, &prev3));
}

test "isInsideTypeOf: trailing comment on a boundary cannot force a match (EPH-I0783)" {
    // Verdict pin from the EPH-I0783 investigation. The pinned rule is
    // narrow. At a depth-0 catch line the comment-stripped boundary check
    // sees the `;` terminator and breaks. This trailing comment cannot
    // force a match. A catch line at deeper paren depth (inside a call
    // argument list) needs the same strip. The sibling test below pins
    // that shape. Comment parens corrupted parenBalance itself until
    // EPH-I0794 masked the primitive; the EPH-I0794 pins cover that class.
    const prev = [_][]const u8{
        "const T = @TypeOf(",
        "    foo,",
        "); // trailing comment",
    };
    const line = "const x = risky() catch unreachable;";
    const col = mem.indexOf(u8, line, "catch").?;
    try std.testing.expect(!isInsideTypeOf(line, col, &prev));
}

test "isInsideTypeOf: comment-hidden boundary, catch at call-arg depth (EPH-I0783)" {
    // The catch line sits at paren depth +1 inside the argument list of a
    // multi-line call. The depth-0 pin above does not cover this shape.
    // The trailing comment on the `);` closer hides the `;` boundary from
    // a raw endsWith check. Without the strip the walk crosses the closed
    // @TypeOf statement. Depth goes positive on its opener line. The check
    // then suppresses a runtime catch unreachable (FN direction, fixed in
    // EPH-I0783).
    const prev = [_][]const u8{
        "    const T = @TypeOf(",
        "        u8,",
        "    ); // keep for later",
    };
    const line = "    const x = foo(bar() catch unreachable,";
    const col = mem.indexOf(u8, line, "catch").?;
    try std.testing.expect(!isInsideTypeOf(line, col, &prev));
    // Control without the comment: the raw boundary check sees the `;`
    // terminator and breaks. The comment is load-bearing in the fixture.
    const bare = [_][]const u8{
        "    const T = @TypeOf(",
        "        u8,",
        "    );",
    };
    try std.testing.expect(!isInsideTypeOf(line, col, &bare));
}

test "isInsideTypeOf: comment parens on a boundary cannot carry the walk (EPH-I0794)" {
    // The EPH-I0783 boundary arm breaks only at depth <= 0. The two `(`
    // in the trailing comment push the naive parenBalance to +1, so the
    // arm never fires and the walk crosses the closed `);` statement
    // into the @TypeOf opener: a runtime catch unreachable is reported
    // as compile-time-only and ZA202 stays silent (FN direction). The
    // masked count reads the boundary line as -1 and the arm breaks.
    const prev = [_][]const u8{
        "const T = @TypeOf(",
        "    foo,",
        "); // reopen ((",
    };
    const line = "const x = risky() catch unreachable;";
    const col = mem.indexOf(u8, line, "catch").?;
    try std.testing.expect(!isInsideTypeOf(line, col, &prev));
}

test "isInsideTypeOf: string parens on a boundary cannot carry the walk (EPH-I0794)" {
    // Same skew through a string literal. The naive count reads the two
    // `(` inside "((" as real opens, defeats the depth-0 boundary arm,
    // and lands on the @TypeOf opener with depth > 0 (ZA202 FN). The
    // masked count skips string data and breaks at the boundary.
    const prev = [_][]const u8{
        "const T = @TypeOf(",
        "    foo,",
        "); const s = \"((\";",
    };
    const line = "const x = risky() catch unreachable;";
    const col = mem.indexOf(u8, line, "catch").?;
    try std.testing.expect(!isInsideTypeOf(line, col, &prev));
}

test "isInsideTypeOf: comment paren on the catch line keeps a genuine match (EPH-I0794)" {
    // The catch sits inside @TypeOf( ... ), so suppression is correct.
    // The naive count reads the `)` in the catch line's own trailing
    // comment as a real close and starts the walk at depth -1. The
    // opener then lifts depth only to 0, the genuine match is lost, and
    // ZA202 fires on compile-time-only code. The masked count starts
    // the walk at 0 and the opener matches at depth +1.
    const prev = [_][]const u8{
        "const T = @TypeOf(",
    };
    const line = "    foo() catch unreachable, // )";
    const col = mem.indexOf(u8, line, "catch").?;
    try std.testing.expect(isInsideTypeOf(line, col, &prev));
}

test "isInsideTypeOf: closed @TypeOf parens do not contain the catch (EPH-I0492)" {
    // F9: the fast path returned true on ANY `@TypeOf(` left of the
    // catch, even a closed one — `const T = @TypeOf(x); y() catch
    // unreachable;` was suppressed though the catch is runtime code. The
    // opener now counts only while its parens stay open at the catch
    // site. The slow path stays untouched.
    const line = "const T = @TypeOf(x); y() catch unreachable;";
    const col = mem.indexOf(u8, line, "catch").?;
    try std.testing.expect(!isInsideTypeOf(line, col, null));
    // Guard: a catch inside an open @TypeOf still suppresses.
    try std.testing.expect(isInsideTypeOf("const T = @TypeOf(foo() catch unreachable);", 30, null));
}

test "ZA202 fires on the closed @TypeOf shape (EPH-I0492)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // End-to-end: the closed `@TypeOf(u8);` on the same line no longer
    // suppresses the runtime `catch unreachable` on the sibling
    // statement.
    const content =
        \\fn f() void {
        \\    const T = @TypeOf(u8); const r = risky() catch unreachable;
        \\    _ = T;
        \\    _ = r;
        \\}
    ;
    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();
    const analysis = try createTestFileAnalysis(allocator, "test_za202_closed_typeof.zig", content);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, "test_za202_closed_typeof.zig"), {});
    var issues = try analyzeErrors(allocator, &graph);
    defer deinitIssues(&issues, allocator);
    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(issues.items, "test_za202_closed_typeof.zig", RULE_CATCH_UNREACHABLE),
    );
}

test "findCallSiteLine: comment parens cannot skip the real opener (EPH-I0794)" {
    // Two skews stack. The `)` in the opener's trailing comment cancels
    // its real `(` in the naive count, so the walk sails past the real
    // call line. The `(` in the bufPrint line's trailing comment then
    // lifts the naive depth to 0 and the walk returns that line, so the
    // bufPrint suppression swallows a runtime catch unreachable (ZA202
    // FN). The masked count balances on the real opener and returns it.
    const prev = [_][]const u8{
        "const a = std.fmt.bufPrint(&buf, \"{d}\", .{x}) catch unreachable; // (",
        "const b = riskyCall( // )",
        "    y,",
    };
    const line = ") catch unreachable;";
    const got = findCallSiteLine(line, &prev) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("const b = riskyCall( // )", got);
    try std.testing.expect(!isBufPrintCatchUnreachable(line, mem.indexOf(u8, line, "catch").?, &prev));
}

test "isDeferCatchMultiline: trailing comment must not hide a boundary (EPH-I0783)" {
    // Pre-fix the raw-line endsWith missed the terminator hidden by the
    // trailing comment, the walk crossed the statement, and an earlier
    // defer justified a catch {} that is not its continuation: a missed
    // ZA201/ZT104 report (FN direction, fixed in EPH-I0783).
    const prev = [_][]const u8{
        "    defer cleanup();",
        "    doWork(); // trailing comment",
    };
    try std.testing.expect(!isDeferCatchMultiline(&prev));
    // The same miss through the block-opener boundary.
    const blk = [_][]const u8{
        "    defer cleanup();",
        "    if (x) { // trailing comment",
    };
    try std.testing.expect(!isDeferCatchMultiline(&blk));
    // The genuine multi-line defer continuation still suppresses.
    const ok = [_][]const u8{
        "    defer std.fs.cwd()",
        "        .openFile(\"x\", .{})",
    };
    try std.testing.expect(isDeferCatchMultiline(&ok));
    // A boundary char inside the trailing comment is not a boundary.
    const cont = [_][]const u8{
        "    defer std.fs.cwd()",
        "        .openFile(\"x\", .{}) // note: {",
    };
    try std.testing.expect(isDeferCatchMultiline(&cont));
}

test "isDeferCatchMultiline: terminated one-line defer returns false (EPH-I0490)" {
    // Pre-fix the keyword match won before the statement-boundary check:
    // `defer a();` ends in `;`, so a catch on the next line is a new
    // statement, not the defer's continuation. The boundary check comes
    // first (EPH-I0490).
    const prev = [_][]const u8{"    defer a();"};
    try std.testing.expect(!isDeferCatchMultiline(&prev));
    const er = [_][]const u8{"    errdefer cleanup();"};
    try std.testing.expect(!isDeferCatchMultiline(&er));
    // A multi-line defer whose keyword line stays open still suppresses.
    const cont = [_][]const u8{"    defer std.fs.cwd()"};
    try std.testing.expect(isDeferCatchMultiline(&cont));
}

test "ZA201 fires on a catch after a terminated one-line defer (EPH-I0490)" {
    // End-to-end: `defer a();` on its own line ends the defer statement,
    // so `b() catch {};` on the next line is an unguarded silent catch.
    // Pre-fix isDeferCatchMultiline returned true and the finding was lost.
    const prev = [_][]const u8{"    defer a();"};
    const issue = checkSilentCatch(.{
        .t = "    b() catch {};",
        .path = "test.zig",
        .line = 2,
        .func_name = "processData",
        .preceding_lines = &prev,
    });
    try std.testing.expect(issue != null);
    try std.testing.expectEqualStrings(RULE_SILENT_CATCH, issue.?.rule);
    // The multi-line defer continuation keeps its suppression.
    const cont = [_][]const u8{
        "    defer std.fs.cwd()",
        "        .openFile(\"x\", .{})",
    };
    const silent = checkSilentCatch(.{
        .t = "        .close() catch {};",
        .path = "test.zig",
        .line = 3,
        .func_name = "processData",
        .preceding_lines = &cont,
    });
    try std.testing.expect(silent == null);
}

