test "isCleanupMethodCall ignores cleanup prose in a trailing comment (EPH-I0409)" {
    // The .close( exists only in comment prose — the catch is not a
    // cleanup call, so ZA201 must fire.
    try std.testing.expect(!isCleanupMethodCall("foo() catch {}; // .close("));
    try std.testing.expect(!isCleanupMethodCall("foo() catch {}; // .deinit( conn"));
    // Real code before the comment still matches.
    try std.testing.expect(isCleanupMethodCall("conn.close() catch {}; // done"));
}

test "isCleanupMethodCall applies camelCase boundaries to keywords (EPH-I0409)" {
    // "close" inside enclose/disclose is a substring, not a cleanup
    // segment — the silent catch on these methods must fire.
    try std.testing.expect(!isCleanupMethodCall("x.enclose() catch {}"));
    try std.testing.expect(!isCleanupMethodCall("x.disclose() catch {}"));
    // Segment starts still match: prefix and camelCase forms.
    try std.testing.expect(isCleanupMethodCall("x.close() catch {}"));
    try std.testing.expect(isCleanupMethodCall("x.onClose() catch {}"));
    try std.testing.expect(isCleanupMethodCall("x.shutdownLeader() catch {}"));
    try std.testing.expect(isCleanupMethodCall("x.leaseRevoke() catch {}"));
}

test "isCleanupMethodCall keeps snake_case segment suppressions (EPH-I0875)" {
    // An underscore before the match is a segment boundary: the
    // snake_case compound peer_teardown keeps its legit ZA201 suppression.
    try std.testing.expect(isCleanupMethodCall("x.peer_teardown() catch {}"));
    try std.testing.expect(isCleanupMethodCall("x.pre_deinit() catch {}"));
    // No boundary still rejects: the keyword must start a segment.
    try std.testing.expect(!isCleanupMethodCall("x.peerteardown() catch {}"));
    try std.testing.expect(!isCleanupMethodCall("x.enclose() catch {}"));
}

test "containsAnyPatternInCode skips string and comment positions (EPH-I0410)" {
    const pats = [_][]const u8{ ".deinit(", "A(" };
    try std.testing.expect(containsAnyPatternInCode("x.deinit();", &pats));
    try std.testing.expect(containsAnyPatternInCode("_ = A(b);", &pats));
    try std.testing.expect(!containsAnyPatternInCode("x = \"a .deinit( b\";", &pats));
    try std.testing.expect(!containsAnyPatternInCode("x = f(\"A(\");", &pats));
    try std.testing.expect(!containsAnyPatternInCode("x = 1; // .deinit(", &pats));
    try std.testing.expect(!containsAnyPatternInCode("x = 1; // A(", &pats));
}

test "containsAnyPatternInCode keeps one classifier per pattern (EPH-I0416)" {
    // The defer_pats shape that armed ZA206: "errdefer " contains
    // "defer " at offset 3, so the second pattern's match can precede
    // the first pattern's last query. A single classifier would break
    // its non-decreasing query invariant and panic (gate dogfood).
    const defer_pats = [_][]const u8{ "defer ", "errdefer " };
    try std.testing.expect(containsAnyPatternInCode("errdefer gpa.free(buf);", &defer_pats));
    // Prose-only "defer " before a real "errdefer ": the first pattern's
    // skipped in-string match must not break the second pattern's walk.
    const mixed = "s = \"defer \"; errdefer gpa.free(buf);";
    try std.testing.expect(containsAnyPatternInCode(mixed, &defer_pats));
    // Prose-only matches still never count as code.
    try std.testing.expect(!containsAnyPatternInCode("x = 1; // defer cleanup", &defer_pats));
    try std.testing.expect(!containsAnyPatternInCode("const s = \"errdefer \";", &defer_pats));
    // General cross-pattern ordering: the second pattern's match ("aaa"
    // at 0) precedes the first pattern's only query (in-string "aa " at
    // 5), so the second pattern re-walks from 0.
    const odd_pats = [_][]const u8{ "aa ", "aaa" };
    try std.testing.expect(containsAnyPatternInCode("aaa(\"aa x\");", &odd_pats));
}

test "isSafeToDiscard ignores discard-masking prose in comments (EPH-I0410)" {
    // A trailing comment naming a cleanup call or FFI shape must not
    // suppress the ZA205 note.
    try std.testing.expect(!isSafeToDiscard("_ = foo(); // .deinit(", null));
    try std.testing.expect(!isSafeToDiscard("_ = foo(); // A(", null));
    try std.testing.expect(!isSafeToDiscard("_ = foo(); // .free(", null));
    // Real cleanup calls stay silent.
    try std.testing.expect(isSafeToDiscard("_ = list.deinit();", null));
}

test "isSafeToDiscard ignores discard-masking prose in strings (EPH-I0410)" {
    // "A(" and cleanup patterns inside string data are text, not calls.
    try std.testing.expect(!isSafeToDiscard("_ = f(\"A(\");", null));
    try std.testing.expect(!isSafeToDiscard("_ = f(\".deinit(\");", null));
}

test "hasDirectFill finds fills after a URL-bearing string literal (EPH-I0412)" {
    // The raw `//` check read the "//" of "http://" as a comment start and
    // skipped the real assignment: x was reported unfilled at scope end
    // (ZA204 false positive).
    try std.testing.expect(hasDirectFill("s = \"http://a\"; x = compute();", "x"));
    try std.testing.expect(hasDirectFill("url = \"https://x/y\"; x = 1;", "x"));
    // Occurrences inside a real trailing comment stay invisible.
    try std.testing.expect(!hasDirectFill("y = f(); // x = 5", "x"));
    try std.testing.expect(!hasDirectFill("y = 1; // x = 5", "x"));
}

test "quote-aware comment guards across the occurrence scans (EPH-I0003)" {
    // The r2_f_url probe shape (`const url = "http://a.b"; x = 1;` + a
    // later read): a `//` inside a string literal before the occurrence
    // is data, not a comment start. The five mid-line `//` guards route
    // through findCommentStart, which is quote-aware.
    try std.testing.expect(hasAddressOfVar("const u = \"http://a\"; f(&x)", "x"));
    try std.testing.expect(hasUntrackableAddressOf("const u = \"http://a\"; const p = &x;", "x"));
    try std.testing.expect(hasMethodCallOnVar("const u = \"http://a\"; x.clear();", "x"));
    try std.testing.expect(hasPayloadBinding("const u = \"http://a\"; for (xs) |x|", "x"));
    try std.testing.expect(hasSlicePassToFunction("const u = \"http://a\"; send(buf[0..])", "buf"));
    // An occurrence after a real trailing comment stays invisible.
    try std.testing.expect(!hasAddressOfVar("f(&y); // &x", "x"));
    try std.testing.expect(!hasPayloadBinding("for (xs) |y| // |x|", "x"));
}

test "a mid-line multiline opener tail never fills (EPH-I0003)" {
    // The q5 probe shape: `const s = \\x = 1` — the tail is string data,
    // so the fill scan must not read the assignment as real code.
    try std.testing.expect(!hasDirectFill("const s = \\\\x = 1;", "x"));
}

test "isFillPattern: a fill-shaped debug string on a for line does not fill (EPH-I0099)" {
    // The deleted hasForLoopIndexedFill matched the `x[i] = ` shape
    // inside the string literal (it had no literal masking): the debug
    // print read as filling x. hasDirectFill pattern 2 masks literals,
    // so the line no longer counts as a fill.
    try std.testing.expect(!isFillPattern("for (items) |i| log(\"x[i] = 1\", .{x[i]});", "x"));
}

test "firstVarReadPos exempts .len occurrences (EPH-I0338 doc)" {
    // The .len exemption is a documented false negative: a slice reads
    // `.len` at runtime, but the type is unknown at this text scan, so
    // every `.len` occurrence stays read-exempt (band-B01b F-12,
    // isReadExemptOccurrence).
    try std.testing.expect(firstVarReadPos("n = s.len;", "s") == null);
    try std.testing.expect(firstVarReadPos("n = buf.len;", "buf") == null);
    // Non-.len occurrences still read.
    try std.testing.expect(firstVarReadPos("n = s.ptr;", "s") != null);
}

test "branchAssignsVar and branchHasExit accept an empty body (EPH-I0341)" {
    // The `lines.len - 1` end cap underflowed on an empty slice (panic
    // in ReleaseSafe, UB in ReleaseFast); the guard returns the
    // documented empty-body verdict instead (band-B01b F-15).
    const empty: []const []const u8 = &.{};
    try std.testing.expect(!branchAssignsVar(empty, 0, 0, "x"));
    try std.testing.expect(!branchHasExit(empty, 0, 0));
}

test "firstVarReadPos ignores string-data comment openers and real comments (EPH-I0412)" {
    // A "//" inside a string literal never fakes a comment: the read of y
    // stays visible.
    try std.testing.expect(firstVarReadPos("s = \"http://a\"; y == 1", "y") != null);
    // Occurrences inside a real trailing comment are prose, not reads.
    try std.testing.expect(firstVarReadPos("x = 1; // y == 1", "y") == null);
}

test "isTryAllocation ignores try prose in strings and comments (EPH-I0298)" {
    // "try " in a trailing comment faked a try allocation on a plain alloc
    // line, forcing errdefer coverage the code never owed.
    try std.testing.expect(!isTryAllocation("const buf = allocator.alloc(u8, 10); // a try b", null));
    try std.testing.expect(!isTryAllocation("const s = \"a try b\"; const buf = allocator.alloc(u8, 10);", null));
    // Real try allocations stay detected.
    try std.testing.expect(isTryAllocation("const buf = try allocator.alloc(u8, 10);", null));
}

test "hasErrorHandling ignores try and catch prose in strings and comments (EPH-I0298)" {
    // Comment and string positions of try/catch never count as error
    // handling, so the discard still reports.
    try std.testing.expect(!hasErrorHandling("_ = f(); // a try b"));
    try std.testing.expect(!hasErrorHandling("_ = f(); // a catch b"));
    try std.testing.expect(!hasErrorHandling("_ = f(\"a try b\");"));
    try std.testing.expect(!hasErrorHandling("_ = f(\"a catch b\");"));
    // Real handling stays detected.
    try std.testing.expect(hasErrorHandling("_ = try f();"));
    try std.testing.expect(hasErrorHandling("_ = f() catch {};"));
}

test "hasBasicIndexGuard and hasAndComparisonGuard ignore prose (EPH-I0298)" {
    const loc_n = IndexExprLoc{ .var_name = "n", .bracket_pos = 17 };
    const loc_i = IndexExprLoc{ .var_name = "i", .bracket_pos = 24 };
    // "while"/"and" in a comment or string never fakes a guard.
    try std.testing.expect(!hasBasicIndexGuard("x = f(); // while a > 0", loc_n));
    try std.testing.expect(!hasBasicIndexGuard("s = \"a while b > 0\";", loc_n));
    try std.testing.expect(!hasAndComparisonGuard("x = f(); // a and b > c", loc_i));
    try std.testing.expect(!hasAndComparisonGuard("s = \"a and b > c\";", loc_i));
    // Real guards stay detected.
    try std.testing.expect(hasBasicIndexGuard("while (n > 0) { a[n - 1]; }", loc_n));
    try std.testing.expect(hasAndComparisonGuard("if (i > 0 and j < n) { a[i - 1]; }", loc_i));
}

test "guard detectors are code-position scans on the independent arms (EPH-I0874)" {
    const loc_i = IndexExprLoc{ .var_name = "i", .bracket_pos = 25 };
    const loc_s = IndexExprLoc{ .var_name = "s.len", .bracket_pos = 27 };
    // The keywordless arms ("endsWith", "startsWith", "== 0 or",
    // "!= 0 and") and the comparison patterns count only at code
    // positions: comment prose and string data never fake a guard.
    try std.testing.expect(!hasBasicIndexGuard("x = f(); // endsWith", loc_s));
    try std.testing.expect(!hasBasicIndexGuard("x = f(); // startsWith", loc_s));
    try std.testing.expect(!hasBasicIndexGuard("x = f(); // i == 0 or j == 0", loc_i));
    try std.testing.expect(!hasBasicIndexGuard("x = f(); // i != 0 and j != 0", loc_i));
    try std.testing.expect(!hasBasicIndexGuard("const s = \"i == 0 or j\";", loc_i));
    try std.testing.expect(!hasBasicIndexGuard("const s = \"endsWith(\\\"x\\\");\";", loc_s));
    try std.testing.expect(!hasAndComparisonGuard("if (a and b) { // x > y", loc_i));
    try std.testing.expect(!hasAndComparisonGuard("if (a and b) { s = \"x > y\"; }", loc_i));
    // Real guards stay detected.
    try std.testing.expect(hasBasicIndexGuard("if (s.endsWith(\".zig\")) { a[s.len - 1]; }", loc_s));
    try std.testing.expect(hasBasicIndexGuard("if (i == 0 or j == 0) { a[i - 1]; }", loc_i));
    try std.testing.expect(hasBasicIndexGuard("if (i != 0 and j != 0) { a[i - 1]; }", loc_i));
    try std.testing.expect(hasAndComparisonGuard("if (i > 0 and j < n) { a[i - 1]; }", loc_i));
}

test "hasLowerBoundGuardForVar rejects or-roots that prove nothing (EPH-I0942)" {
    // band-B12 F17 residual: the `>` arm had no tail discipline —
    // `y > 0 or x > 0` ran the guarded body at x == 0 when only y
    // held, so the subtraction stayed silent. The `!=` arm's raw
    // `" or"` check also missed the whitespace variant `x != 0  or y`.
    // Both arms now reject any or-root that proves nothing for the var;
    // an `and`-tail and a same-var or-root keep the guard.
    const limit: usize = 1000;
    try std.testing.expect(!hasLowerBoundGuardForVar("while (y > 0 or x > 0) a[x - 1];", "x", limit));
    try std.testing.expect(!hasLowerBoundGuardForVar("while (x > 0 or y > 0) a[x - 1];", "x", limit));
    try std.testing.expect(!hasLowerBoundGuardForVar("while (x > 0 or y) a[x - 1];", "x", limit));
    try std.testing.expect(!hasLowerBoundGuardForVar("while (x != 0 or y) a[x - 1];", "x", limit));
    try std.testing.expect(!hasLowerBoundGuardForVar("while (x != 0  or y) a[x - 1];", "x", limit));
    try std.testing.expect(hasLowerBoundGuardForVar("while (x > 0 and y) a[x - 1];", "x", limit));
    try std.testing.expect(hasLowerBoundGuardForVar("while (x > 0 or x > 5) a[x - 1];", "x", limit));
    try std.testing.expect(hasLowerBoundGuardForVar("while (x > 0) a[x - 1];", "x", limit));
}

test "hasExitKeyword ignores exit keywords in strings and comments (EPH-I0298)" {
    // Exit keywords in prose never prove the over-limit path exits.
    try std.testing.expect(!hasExitKeyword("x = f(); // return"));
    try std.testing.expect(!hasExitKeyword("x = f(); // break"));
    try std.testing.expect(!hasExitKeyword("x = f(); // continue"));
    try std.testing.expect(!hasExitKeyword("x = f(); // unreachable"));
    try std.testing.expect(!hasExitKeyword("x = f(); // orelse"));
    try std.testing.expect(!hasExitKeyword("x = \"a return b\";"));
    // Real exit keywords stay detected.
    try std.testing.expect(hasExitKeyword("if (x >= N) return;"));
    try std.testing.expect(hasExitKeyword("if (x >= N) unreachable;"));
}

test "isStreamWriteCall matches writeSep pattern" {
    try std.testing.expect(isStreamWriteCall("ctr.writeSep(writer) catch {}"));
}

// ============================================================================
// ZA305/ZA306 — Cyclomatic and Cognitive Complexity Tests
// ============================================================================

// --- Unit tests for helper functions ---

test "countLineCyclomatic counts all decision points" {
    // Control flow keywords
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("if (x) {"));
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("} else if (y) {"));
    // else adds no decision point (McCabe; the README decision list names
    // no else) — EPH-I0455.
    try std.testing.expectEqual(@as(usize, 0), countLineCyclomatic("} else {"));
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("for (items) |item| {"));
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("switch (x) {"));
    // Error handling
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("try foo();"));
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("x catch |e| {"));
    // Null coalescing and logical operators
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("const v = x orelse return;"));
    try std.testing.expectEqual(@as(usize, 2), countLineCyclomatic("if (a and b) {"));
    try std.testing.expectEqual(@as(usize, 2), countLineCyclomatic("if (a or b) {"));
    // Multiple decision points on one line
    try std.testing.expectEqual(@as(usize, 2), countLineCyclomatic("if (a and b) |v| {"));
    try std.testing.expectEqual(@as(usize, 2), countLineCyclomatic("try foo() catch |e| { return e; };"));
    // No decision points
    try std.testing.expectEqual(@as(usize, 0), countLineCyclomatic("var x: u32 = 0;"));
    try std.testing.expectEqual(@as(usize, 0), countLineCyclomatic("_ = allocator;"));
    try std.testing.expectEqual(@as(usize, 0), countLineCyclomatic("return .{};"));
    // Inline loops excluded (checked via hasRuntimeLoop)
    try std.testing.expectEqual(@as(usize, 0), countLineCyclomatic("inline for (fields) |f| {"));
    try std.testing.expectEqual(@as(usize, 0), countLineCyclomatic("inline while (cond) {"));
}

test "countLineCognitive weights by nesting and counts else/orelse" {
    // Top level (nest=0): 1 cost each
    try std.testing.expectEqual(@as(usize, 1), countLineCognitive("if (x) {", 0, 0));
    try std.testing.expectEqual(@as(usize, 1), countLineCognitive("while (true) {", 0, 0));
    try std.testing.expectEqual(@as(usize, 1), countLineCognitive("for (items) |item| {", 0, 0));
    try std.testing.expectEqual(@as(usize, 1), countLineCognitive("switch (x) {", 0, 0));
    // try has no structural increment (Sonar; the README rule lists no try)
    // — EPH-I0458.
    try std.testing.expectEqual(@as(usize, 0), countLineCognitive("try foo();", 0, 0));
    try std.testing.expectEqual(@as(usize, 1), countLineCognitive("x catch |e| {", 0, 0));
    // else costs 1 at the closed scope's level (else_nest) but doesn't
    // increase nesting
    try std.testing.expectEqual(@as(usize, 1), countLineCognitive("} else {", 0, 0));
    try std.testing.expectEqual(@as(usize, 2), countLineCognitive("} else {", 2, 1));
    // Nest level 3: 1 + 3 = 4
    try std.testing.expectEqual(@as(usize, 4), countLineCognitive("if (x) {", 3, 3));
    try std.testing.expectEqual(@as(usize, 4), countLineCognitive("while (true) {", 3, 3));
    // orelse always costs 1 regardless of nesting
    try std.testing.expectEqual(@as(usize, 1), countLineCognitive("x orelse return;", 0, 0));
    try std.testing.expectEqual(@as(usize, 1), countLineCognitive("x orelse return;", 3, 3));
    // and/or always cost 1 regardless of nesting
    try std.testing.expectEqual(@as(usize, 2), countLineCognitive("if (a and b) {", 0, 0));
    try std.testing.expectEqual(@as(usize, 7), countLineCognitive("if (a and b) {", 5, 5));
    // Non-branching lines cost 0
    try std.testing.expectEqual(@as(usize, 0), countLineCognitive("var x: u32 = 0;", 0, 0));
    try std.testing.expectEqual(@as(usize, 0), countLineCognitive("x += 1;", 3, 3));
}

test "opensCognitiveScope detects control keyword + brace" {
    try std.testing.expect(opensCognitiveScope("if (x) {"));
    try std.testing.expect(opensCognitiveScope("while (true) {"));
    try std.testing.expect(opensCognitiveScope("for (items) |item| {"));
    try std.testing.expect(opensCognitiveScope("switch (x) {"));
    try std.testing.expect(opensCognitiveScope("try foo() catch |e| {"));
    try std.testing.expect(!opensCognitiveScope("var x: u32 = 0;"));
    try std.testing.expect(!opensCognitiveScope("if (x) return;"));
    // EPH-I0453: else opens the else block's scope, so its body measures
    // at the same cog_nest as the matching if body.
    try std.testing.expect(opensCognitiveScope("} else {"));
}

test "countLineCyclomatic ignores keywords in strings and comments (EPH-I0226)" {
    // Raw substring counting reported each of these as 4 decision points.
    try std.testing.expectEqual(@as(usize, 0), countLineCyclomatic("foo(); // try and or orelse"));
    try std.testing.expectEqual(@as(usize, 0), countLineCyclomatic("// try and or orelse"));
    try std.testing.expectEqual(
        @as(usize, 0),
        countLineCyclomatic("const s = \"try and or orelse\";"),
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        countLineCyclomatic("const s = \"try \\\"and\\\" or orelse\";"),
    );
    // Real tokens keep their counts (cardinality unchanged).
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("try foo();"));
    try std.testing.expectEqual(@as(usize, 2), countLineCyclomatic("if (a and b) {"));
    try std.testing.expectEqual(@as(usize, 2), countLineCyclomatic("if (a or b) {"));
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("const v = x orelse return;"));
}

test "countSwitchArms ignores arrows in trailing comments (EPH-I0017)" {
    // hasToken is comment-masked since B2; countSwitchArms was the
    // leftover: `foo(); // a => b` counted a phantom arm in ZA304/305/306.
    try std.testing.expectEqual(@as(usize, 0), countSwitchArms("foo(); // a => b"));
    try std.testing.expectEqual(@as(usize, 0), countSwitchArms("// =>"));
    try std.testing.expectEqual(@as(usize, 1), countSwitchArms("0 => 1, // a => b"));
    try std.testing.expectEqual(@as(usize, 2), countSwitchArms("0 => 1, 2 => 3, // x => y"));
    // String arrows stay masked too (pre-existing EPH-I0153 behavior).
    try std.testing.expectEqual(@as(usize, 0), countSwitchArms("const s = \"=>\";"));
}

test "complexity counters ignore a comment arrow on a real branch line (EPH-I0017)" {
    // The ZA304/305/306 paths: one real arm plus a commented `=>` counts
    // the arm only.
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("0 => 1, // a => b"));
    try std.testing.expectEqual(@as(usize, 1), countLineBranches("0 => 1, // a => b"));
    try std.testing.expectEqual(@as(usize, 1), countLineCognitive("0 => 1, // a => b", 0, 0));
    try std.testing.expectEqual(@as(usize, 1), countLineCyclomatic("if (x) foo(); // a => b"));
}

test "trackBraceNesting ignores braces inside trailing comments (EPH-I0017)" {
    // LiteralState masks comment text (types.zig updateForChar), so the
    // `}` in the trailing comment never closes the block: the line nets
    // one open at nest 2 and the fn is not ended. Pin documents the
    // accepted state — the P2-4 addendum's premise (LiteralState does not
    // model `//`) is stale at HEAD.
    var state = ComplexityState{ .in_fn = true, .nest = 1 };
    try std.testing.expect(!trackBraceNesting("if (x) { // }", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
    // The close-in-comment twin: `}` in the comment must not end the fn.
    var state2 = ComplexityState{ .in_fn = true, .nest = 1 };
    try std.testing.expect(!trackBraceNesting("if (x) { // } }", &state2));
    try std.testing.expectEqual(@as(usize, 2), state2.nest);
}

test "countLineCognitive ignores keywords in strings and comments (EPH-I0226)" {
    try std.testing.expectEqual(
        @as(usize, 0),
        countLineCognitive("foo(); // try and or orelse", 0, 0),
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        countLineCognitive("const s = \"try and or orelse\";", 3, 3),
    );
    // Real tokens keep their counts at any nesting level.
    try std.testing.expectEqual(@as(usize, 0), countLineCognitive("try foo();", 0, 0));
    try std.testing.expectEqual(@as(usize, 0), countLineCognitive("try foo();", 3, 3));
    try std.testing.expectEqual(@as(usize, 4), countLineCognitive("foo() catch |e| {}", 3, 3));
    try std.testing.expectEqual(@as(usize, 2), countLineCognitive("if (a and b) {", 0, 0));
    try std.testing.expectEqual(@as(usize, 1), countLineCognitive("x orelse return;", 3, 3));
}

test "opensCognitiveScope ignores a try in a string or comment (EPH-I0226)" {
    try std.testing.expect(!opensCognitiveScope("foo(); // try {"));
    try std.testing.expect(!opensCognitiveScope("const s = \"try {\";"));
    try std.testing.expect(opensCognitiveScope("try foo() catch |e| {"));
}

test "ZA305: keyword-heavy trailing comment does not inflate CCN (EPH-I0226)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();

    // 14 real decision points (CCN 15). The threshold is pinned
    // explicitly at 15: this test pins comment-inflation, not the
    // default threshold (10 since EPH-I0992). The trailing comment
    // added 4 phantom points pre-fix (raw 19) and fired ZA305. The
    // nested chain keeps the fn out of the flat-chain 2x multiplier.
    const code =
        \\fn commentInflated(x: u32) u32 {
        \\    if (x == 1) {
        \\        if (x == 2) {
        \\            if (x == 3) {
        \\                if (x == 4) {
        \\                    if (x == 5) {
        \\                        if (x == 6) {
        \\                            if (x == 7) {
        \\                                if (x == 8) return 8;
        \\                            }
        \\                        }
        \\                    }
        \\                }
        \\            }
        \\        }
        \\    }
        \\    if (x == 9) return 9;
        \\    if (x == 10) return 10;
        \\    if (x == 11) return 11;
        \\    if (x == 12) return 12;
        \\    if (x == 13) return 13;
        \\    if (x == 14) return 14;
        \\    return 0; // try and or orelse
        \\}
    ;
    const analysis = try createTestFileAnalysis(allocator, "comment.zig", code);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, "comment.zig"), {});

    const th = Thresholds{ .max_cyclomatic = 15 };
    var issues = try analyzeComplexity(allocator, &graph, th);
    defer deinitIssues(&issues, allocator);
    try expectNoCyclomaticWarnings(issues.items, "comment.zig");
}

// --- EPH-I0225: bounded backward-scan windows ---

/// Fill every slot with `filler`, then place `guard` at `guard_idx`.
fn guardScanFixture(
    buf: [][]const u8,
    filler: []const u8,
    guard: []const u8,
    guard_idx: usize,
) [][]const u8 {
    for (buf) |*slot| slot.* = filler;
    buf[guard_idx] = guard;
    return buf;
}

test "hasNullGuard finds a guard inside the lookback window (EPH-I0225)" {
    var buf: [8][]const u8 = undefined;
    const lines = guardScanFixture(&buf, "work();", "if (x == null) return;", 1);
    try std.testing.expect(hasNullGuard(lines, lines.len - 1, 0, "x"));
}

test "line-tier orelse after a signature-line null guard stays silent (EPH-I0891)" {
    // The guard sits on the fn signature line. The lookback floor is the
    // signature line's 0-based index: a 1-based floor excludes the line
    // and the line tier fires a ZA203 FP on the orelse below while the
    // CFG tier suppresses (EPH-I0891).
    var issues: std.ArrayListUnmanaged(Issue) = .empty;
    defer issues.deinit(std.testing.allocator);
    var state = ErrorAnalysisState{};
    const lines = [_][]const u8{
        "fn f() u8 { if (p == null) return 0; }",
        "    const x = p orelse unreachable;",
    };
    var ctx = FileErrorScanCtx{
        .allocator = std.testing.allocator,
        .issues = &issues,
        .path = "src/app.zig",
        .all_lines = &lines,
        .state = &state,
    };
    try scanFileErrorLine(&ctx, lines[0], 0);
    try scanFileErrorLine(&ctx, lines[1], 1);
    try std.testing.expectEqual(@as(usize, 0), issues.items.len);
}

test "func_start zero floor may match a guard in a previous fn (EPH-I0891)" {
    // Outside a function (func_start == 0) the floor is the file start:
    // the 20-line window can reach a guard in an earlier function. The
    // consult is adjudicated as accepted module-level behavior (the
    // module-level orelse is comptime), pinned as a probe (EPH-I0891).
    const lines = [_][]const u8{
        "fn earlier(p: ?*u8) u8 {",
        "    if (p == null) return 0;",
        "}",
        "    const x = p orelse unreachable;",
    };
    try std.testing.expect(hasNullGuard(&lines, 3, 0, "p"));
}

test "hasNullCheckExit accepts a compound-line guard exit (EPH-I0892)" {
    // A leading call's paren group precedes the guard's own `if (...)`
    // group: the same-line exit is judged from the guard's group close,
    // not the call's (EPH-I0892).
    var buf: [4][]const u8 = undefined;
    const lines = guardScanFixture(&buf, "work();", "sink(x); if (p == null) return 0;", 1);
    const eq_pos = findTagInCode(lines[1], "== null", 0) orelse return error.TestUnexpectedResult;
    const lookup = NullGuardLookup{ .lines = lines, .i = 1, .limit = lines.len };
    try std.testing.expect(hasNullCheckExit(lines[1], lookup, eq_pos));
}

test "hasNullCheckExit anchors the guard's own code-position predicate (EPH-I0899)" {
    // A leading call whose string carries `== null` before the guard's
    // real `== null`: the caller passes the code-position anchor, so the
    // judge examines the guard's condition group, not the string's. The
    // old whole-line re-find anchored on the string position and the
    // guard lost its same-line exit (EPH-I0899).
    var buf: [4][]const u8 = undefined;
    const lines = guardScanFixture(
        &buf,
        "work();",
        "std.debug.print(\"== null\", .{}); if (p == null) return 0;",
        1,
    );
    const eq_pos = findTagInCode(lines[1], "== null", 0) orelse return error.TestUnexpectedResult;
    const lookup = NullGuardLookup{ .lines = lines, .i = 1, .limit = lines.len };
    try std.testing.expect(hasNullCheckExit(lines[1], lookup, eq_pos));
    // The anchor is the code position: the raw first match sits inside
    // the string and must not be used.
    const raw_pos = mem.indexOf(u8, lines[1], "== null") orelse return error.TestUnexpectedResult;
    try std.testing.expect(raw_pos < eq_pos);
}

test "hasNullGuard ignores == null inside a string (EPH-I0899)" {
    // A string carrying `== null` is data, not a guard predicate: the raw
    // whole-line match admitted the line, and the string position anchored
    // the judge on the leading call's group, whose tail (`return p;`) read
    // as an exit and suppressed the report (EPH-I0899).
    const lines = [_][]const u8{
        "std.debug.print(\"== null\", .{}); return p;",
        "const y = p orelse unreachable;",
    };
    try std.testing.expect(!hasNullGuard(&lines, 1, 0, "p"));
    // The next-line-exit variant: the string line plus an unrelated
    // `return` line must not suppress either (EPH-I0899).
    const next_exit = [_][]const u8{
        "std.debug.print(\"== null\", .{}); const x = p;",
        "return 0;",
        "const y = p orelse unreachable;",
    };
    try std.testing.expect(!hasNullGuard(&next_exit, 2, 0, "p"));
}

test "hasNullGuard requires the == null predicate to bind the checked name (EPH-I0902)" {
    // The name on the guard line is not the null-check operand:
    // `use(p);` precedes q's guard, so q's exit does not cover p and
    // p's ZA203 must fire. Pre-fix the name-plus-`== null` line gate
    // admitted the line and suppressed the report (EPH-I0902).
    const cross = [_][]const u8{
        "use(p); if (q == null) return 0;",
        "const y = p orelse unreachable;",
    };
    try std.testing.expect(!hasNullGuard(&cross, 1, 0, "p"));
    // The genuine same-line form still suppresses: the predicate's
    // operand IS the checked name.
    const genuine = [_][]const u8{
        "if (p == null) return 0;",
        "const y = p orelse unreachable;",
    };
    try std.testing.expect(hasNullGuard(&genuine, 1, 0, "p"));
    // A combined condition binds through the second predicate: the
    // return fires whenever p is null, so p's orelse stays silent.
    const combined = [_][]const u8{
        "if (q == null && p == null) return 0;",
        "const y = p orelse unreachable;",
    };
    try std.testing.expect(hasNullGuard(&combined, 1, 0, "p"));
}

test "line-tier ZA203 fires when the guard line binds another name (EPH-I0902)" {
    var issues: std.ArrayListUnmanaged(Issue) = .empty;
    defer issues.deinit(std.testing.allocator);
    var state = ErrorAnalysisState{};
    const lines = [_][]const u8{
        "fn f(p: ?*u8, q: ?*u8) u8 {",
        "    use(p); if (q == null) return 0;",
        "    const x = p orelse unreachable;",
        "    return x.*;",
        "}",
    };
    var ctx = FileErrorScanCtx{
        .allocator = std.testing.allocator,
        .issues = &issues,
        .path = "src/app.zig",
        .all_lines = &lines,
        .state = &state,
    };
    try scanFileErrorLine(&ctx, lines[0], 0);
    try scanFileErrorLine(&ctx, lines[1], 1);
    try scanFileErrorLine(&ctx, lines[2], 2);
    try scanFileErrorLine(&ctx, lines[3], 3);
    try std.testing.expectEqual(@as(usize, 1), issues.items.len);
    try std.testing.expectEqualStrings(RULE_ORELSE_UNREACHABLE, issues.items[0].rule);
}

test "hasNullCheckExit judges the guard's own nested conditional (EPH-I0892)" {
    // The nested-exit rejection applies to the guard's own group even
    // when a leading call precedes it: the guard block falls through on
    // q false, so the exit does not qualify (EPH-I0859 judgment,
    // EPH-I0892 anchoring).
    var buf: [4][]const u8 = undefined;
    const lines = guardScanFixture(&buf, "work();", "sink(x); if (p == null) { if (q) return 0; }", 1);
    const eq_pos = findTagInCode(lines[1], "== null", 0) orelse return error.TestUnexpectedResult;
    const lookup = NullGuardLookup{ .lines = lines, .i = 1, .limit = lines.len };
    try std.testing.expect(!hasNullCheckExit(lines[1], lookup, eq_pos));
}

test "hasEarlyReturnNullGuard accepts a compound-line guard (EPH-I0892)" {
    // The ZA801 routing inherits the anchored judge: a leading call on
    // the guard line must not move the exit verdict to the call's tail
    // (EPH-I0892).
    const lines = [_][]const u8{
        "fn f(p: ?*u8) u8 {",
        "    sink(x); if (p == null) return 0;",
        "    const v = p.*;",
    };
    try std.testing.expect(hasEarlyReturnNullGuard(&lines, 2, "p"));
}

test "guardLineHasSameLineExit anchors the predicate's group (EPH-I0892)" {
    // The judge anchors on the paren group that contains the predicate:
    // a leading call's group owns an earlier span and its tail is not
    // the guard's (EPH-I0892).
    const line = "sink(x); if (p == null) return 0;";
    const eq_pos = mem.indexOf(u8, line, "== null") orelse return error.TestUnexpectedResult;
    try std.testing.expect(guardLineHasSameLineExit(line, eq_pos));
    // The nested-exit rejection applies to the guard's own group even on
    // a compound line (EPH-I0859 judgment, EPH-I0892 anchoring).
    const nested = "sink(x); if (p == null) { if (q) return 0; }";
    const nested_eq = mem.indexOf(u8, nested, "== null") orelse return error.TestUnexpectedResult;
    try std.testing.expect(!guardLineHasSameLineExit(nested, nested_eq));
}

test "hasNullEqualityCheck returns the predicate position (EPH-I0892)" {
    // The position points at the `==` of the var's own null check, the
    // anchor for the guard's condition group (EPH-I0892).
    const line = "sink(x); if (p == null) return 0;";
    const eq_pos = hasNullEqualityCheck(line, "p") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("== null)", line[eq_pos .. eq_pos + "== null)".len]);
    try std.testing.expect(hasNullEqualityCheck(line, "q") == null);
    try std.testing.expect(hasNullEqualityCheck("if (p == null) return 0;", "p") != null);
    try std.testing.expect(hasNullEqualityCheck("if (p == 0) return 0;", "p") == null);
}

test "hasNullCheckExit rejects a same-line nested conditional exit (EPH-I0861)" {
    var buf: [4][]const u8 = undefined;
    const lines = guardScanFixture(&buf, "work();", "if (x == null) { if (q) return; }", 1);
    // The same-line exit sits inside a nested conditional: the guard
    // block falls through when q is false, so the exit does not qualify
    // (EPH-I0859 judgment, ZA203-family site).
    const eq_pos = findTagInCode(lines[1], "== null", 0) orelse return error.TestUnexpectedResult;
    const lookup = NullGuardLookup{ .lines = lines, .i = 1, .limit = lines.len };
    try std.testing.expect(!hasNullCheckExit(lines[1], lookup, eq_pos));
}

test "hasNullCheckExit accepts a same-line direct exit (EPH-I0861)" {
    var buf: [4][]const u8 = undefined;
    const lines = guardScanFixture(&buf, "work();", "if (x == null) return;", 1);
    const eq_pos = findTagInCode(lines[1], "== null", 0) orelse return error.TestUnexpectedResult;
    const lookup = NullGuardLookup{ .lines = lines, .i = 1, .limit = lines.len };
    try std.testing.expect(hasNullCheckExit(lines[1], lookup, eq_pos));
    const braced = guardScanFixture(&buf, "work();", "if (x == null) { return; }", 1);
    const braced_eq = findTagInCode(braced[1], "== null", 0) orelse return error.TestUnexpectedResult;
    const braced_lookup = NullGuardLookup{ .lines = braced, .i = 1, .limit = braced.len };
    try std.testing.expect(hasNullCheckExit(braced[1], braced_lookup, braced_eq));
    // A continued condition keeps its exit: the condition close is the
    // whole paren group, not the `== null)` position (EPH-I0861).
    const continued = guardScanFixture(&buf, "work();", "if (x == null || q) return;", 1);
    const continued_eq = findTagInCode(continued[1], "== null", 0) orelse
        return error.TestUnexpectedResult;
    const continued_lookup = NullGuardLookup{ .lines = continued, .i = 1, .limit = continued.len };
    try std.testing.expect(hasNullCheckExit(continued[1], continued_lookup, continued_eq));
}

test "hasSameLineGuardExit applies the depth-2 then+else rule (EPH-I0861)" {
    // A nested conditional whose then and else arms both exit dominates
    // the guard's fall-through like a direct exit: the same-line form of
    // the walk's depth-2 rule (EPH-I0861).
    try std.testing.expect(hasSameLineGuardExit("{ if (q) { return null; } else { return null; } }"));
    // Nested without an else stays rejected: the q-false path falls
    // through (EPH-I0859).
    try std.testing.expect(!hasSameLineGuardExit("{ if (q) return null; }"));
    // The outer-else family (the guard's own else arm) is not the nested
    // conditional's else: the then-arm's nested exit alone does not
    // qualify, so the shape fires (EPH-I0861).
    try std.testing.expect(!hasSameLineGuardExit("{ if (q) return null; } else { return null; }"));
    // Direct and braced direct exits keep their depth-1 acceptance.
    try std.testing.expect(hasSameLineGuardExit("return null;"));
    try std.testing.expect(hasSameLineGuardExit("{ return null; }"));
    // The else-if chain can still fall through: rejected like the walk's
    // plain-else-opener rule (EPH-I0861).
    try std.testing.expect(!hasSameLineGuardExit("{ if (q) { return null; } else if (r) { return null; } }"));
    // An else arm without an exit does not qualify.
    try std.testing.expect(!hasSameLineGuardExit("{ if (q) { return null; } else { work(); } }"));
    // The unbraced-then twin of the both-arms rule: the then arm is a
    // direct exit without braces. The else-terminated layout carries no
    // semicolon at the arm end (`if (q) return null else { return null; }`,
    // the Zig grammar's AssignExpr KEYWORD_else form, EPH-I0861).
    try std.testing.expect(hasSameLineGuardExit("{ if (q) return null else { return null; } }"));
    // The semicolon spelling (`if (q) return null; else { return null; }`)
    // is a Zig parse error; the judge accepts it anyway through the
    // else-fragment join, so a broken file's guard still suppresses the
    // same way (EPH-I0861).
    try std.testing.expect(hasSameLineGuardExit("{ if (q) return null; else { return null; } }"));
    // The unbraced-then twin stays rejected when the else arm does not
    // exit: the q-false path falls through (EPH-I0861).
    try std.testing.expect(!hasSameLineGuardExit("{ if (q) return null else { work(); } }"));
    // A then arm that is not a direct exit stays rejected: the q-true
    // path falls through (EPH-I0861).
    try std.testing.expect(!hasSameLineGuardExit("{ if (q) work() else { return null; } }"));
}

test "analyzeCFGMemory ZA203 fires past a same-line nested conditional exit in a braced guard (EPH-I0861)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // `if (p == null) { if (q) return 0; }` on one line: the exit sits
    // inside a nested conditional, so the block falls through when q is
    // false and `p orelse unreachable` panics on null. The substring
    // same-line exit gate suppressed it; the depth judgment lets ZA203
    // fire (EPH-I0861).
    const content =
        \\fn za203_same_line_nested(p: ?*u8, q: bool) u8 {
        \\    if (p == null) { if (q) return 0; }
        \\    const x = p orelse unreachable;
        \\    return x.*;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "test_za203_sameline_nested.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        1,
        countRuleIssues(run.issues.items, "test_za203_sameline_nested.zig", RULE_ORELSE_UNREACHABLE),
    );
}

