    const code =
        \\fn i0133_repro(v: u8) void {
        \\    switch (v) {
        \\        0 => sink(0),
        \\        1 => sink(1),
        \\        else => {},
        \\    }
    ++ "\n" ++ "    sink(2);\n" ** 54 ++
        \\}
