        \\    _ = v;
        \\}
    ;
    try expectMeasuredFnLines(&diag, allocator, .{ .file = "i0133.zig", .code = code, .expect_lines = 61 });
}

test "ZA301: block-prong switch with code after it measures to the fn end (EPH-I0451)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // handleBlockEnd-shaped: four block prongs, then work after the
    // switch. True body 52 lines; pre-fix the second prong close ended
    // the measurement at fn line 10.
    const code =
        \\fn handle_block_end_shaped(v: u8) void {
        \\    switch (v) {
        \\        .catch_block => {
        \\            edge();
        \\            set_line();
        \\        },
        \\        .while_block, .for_block => {
        \\            edge();
        \\            set_line();
        \\        },
        \\        .switch_block => {
        \\            edge();
        \\            set_line();
        \\        },
        \\        else => {
        \\            edge();
        \\            set_line();
        \\        },
        \\    }
    ++ "\n" ++ "    after();\n" ** 32 ++
        \\}
        \\fn edge() void {}
        \\fn set_line() void {}
        \\fn after() void {}
    ;
    try expectMeasuredFnLines(&diag, allocator, .{ .file = "hbe.zig", .code = code, .expect_lines = 52 });
