    // so the wrapped `) type {` factory measured at the 50 limit and
    // fired; the [tf] 3x limit (150) keeps it silent.
    const factory =
        \\fn WrappedFactory(
        \\    comptime T: type,
        \\) type {
        \\    const S = struct { x: T };
    ++ "\n" ++ "    _ = T;\n" ** 54 ++
        \\    return S;
        \\}
    ;
