    // the hold at the statement, missing the double lock. Regression
    // pin (band B08 F3).
    const content =
        \\fn doWork() void {}
        \\fn f(x: bool) void {
        \\    mu.lock();
        \\    if (x) { doWork(); } defer mu.unlock();
