    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Guard pin for the analyzeCFGFile trackTestBlock site (:22831).
    // The isCommentOrMultilineString check at :22828 precedes the tracker
    // call at :22831 (verified order), and trackTestBlock masks in-line
    // strings itself (EPH-I0883). A test block whose name carries `{`,
    // whose body carries a `"}"` fixture and a trailing `// }` comment
    // must still bound exactly: the no-free fn INSIDE the block is test
    // context (r3 suppressed), the twin OUTSIDE fires ZA103.
    const content =
        \\fn outside(allocator: std.mem.Allocator, x: u8) !void {
        \\    const buf = try allocator.alloc(u8, 100);
        \\    _ = buf;
        \\    if (x > 0) return error.bad;
        \\}
        \\test "alloc {" {
        \\    const s = "}";
        \\    _ = s;
        \\    fn inside(allocator: std.mem.Allocator, x: u8) !void {
        \\        const buf = try allocator.alloc(u8, 100);
        \\        _ = buf;
        \\        if (x > 0) return error.bad;
        \\    }
        \\    doWork(); // }
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "za103_shapes.zig", content);
    defer run.deinit(allocator);

    // Only the outside twin fires; the inside fn is test-context.
    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(run.issues.items, "za103_shapes.zig", RULE_ALLOC_NO_ERRDEFER),
    );
}

// ============================================================================
// ZA110 Tests — must-return-ref (managed container returned by value)
// ============================================================================

/// Test helper: build a one-file graph and run the errors pipeline.
fn runErrorsCheck(
    diag: *DiagCtx,
    allocator: Allocator,
    path: []const u8,
    content: []const u8,
) !CFGTestRun {
    var graph = ImportGraph.init(allocator, diag);
    errdefer graph.deinit();
    const analysis = try createTestFileAnalysis(allocator, path, content);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, path), {});
    var issues = try analyzeErrors(allocator, &graph);
    errdefer deinitIssues(&issues, allocator);
    return .{ .graph = graph, .issues = issues };
}

test "ZA110: plain ownership-transfer idiom is silent (established pattern)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // `var list = ...; return list;` with no armed defer: the local is dead
    // after the copy and the caller holds the only owner. Firing here is a
    // false positive (39/39 hits on ephor itself were this idiom).
    const content =
        \\const std = @import("std");
        \\fn makeList(a: std.mem.Allocator) std.ArrayList(u8) {
        \\    var list = std.ArrayList(u8).init(a);
        \\    return list;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "za110_basic.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        @as(usize, 0),
        countRuleIssues(run.issues.items, "za110_basic.zig", RULE_MUST_RETURN_REF),
    );
}

