    var found_name = false;
    for (run.issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_USELESS_ERROR_RETURN) and
            mem.eql(u8, issue.file, "za209_quoted.zig") and
            mem.indexOf(u8, issue.message, "never-fails") != null)
        {
            found_name = true;
        }
