test "ZA904: a clamp rhs on the next line loses the proof — pinned residual (EPH-I0971)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // `const c = @min(x,` / `255);` — the clamp rhs continues on the
    // next line, so the opener line carries no complete statement for
    // the clamp-identity judge and the cast fires a spurious note. The
    // shape is not zig-fmt-canonical (zig fmt joins the call onto one
    // line), the failure direction is conservative (noise, never a
    // missed defect), and the residual is documented at
    // statementCarriesClamp. Pinned here so a future fix flips the
    // verdict deliberately (EPH-I0971).
    const content =
        \\fn cont_clamp(x: u32) u8 {
        \\    const c = @min(x,
        \\        255);
        \\    return @as(u8, @intCast(c));
        \\}
    ;
    var run = try runIntCastTest(&diag, allocator, "app_cont_clamp.zig", content);
    defer run.deinit(allocator);
    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(run.issues.items, "app_cont_clamp.zig", RULE_INTCAST_NO_BOUNDS),
    );
}

test "ZA904: a bare } container close on its own line keeps the loop close real (EPH-I0973)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // A multiline-string array element list closed by a bare `}` on its
    // own line with `;` on the next is valid Zig (zig fmt rewrites the
    // shape to `};`). The bare `}` is code: the loop's own close still
    // drives the lookback depth negative and the out-of-loop cast
    // fires. Pre-fix the bare `}` was masked as string content, the
    // container stayed open, and the for-header wrongly proved the cast
    // (EPH-I0973).
    const content =
        \\fn f(n: usize) u8 {
        \\    for (0..n) |i| {
        \\        const arr = .{ \\a ,
        \\            \\b ,
        \\        }
        \\        ;
        \\        _ = arr;
        \\    }
        \\    return @as(u8, @intCast(i));
        \\}
    ;
    var run = try runIntCastTest(&diag, allocator, "app_bare_brace_fn.zig", content);
    defer run.deinit(allocator);
    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(run.issues.items, "app_bare_brace_fn.zig", RULE_INTCAST_NO_BOUNDS),
    );
}

test "ZA904: broken ) } continuations in invalid regions stay masked (EPH-I0974)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // `const msg = \\usage` then `) } weird` (or `} ;`) is invalid Zig
    // (zig ast-check: expected ';' after statement). The closer arms
    // must not unmask such lines: the prose tail is not a valid closer,
    // and `} ;` without an open container is a broken block close, so
    // both stay string content and the in-loop cast keeps its range-for
    // proof. Pre-fix both fired a spurious note (EPH-I0974).
    const content =
        \\fn paren_broken(n: usize) u8 {
        \\    for (0..n) |i| {
        \\        const msg = \\usage
        \\        ) } weird
        \\        use8(@intCast(i));
        \\        _ = msg;
        \\    }
        \\}
        \\fn brace_broken(n: usize) u8 {
        \\    for (0..n) |i| {
        \\        const msg = \\usage
        \\        } ;
        \\        use8(@intCast(i));
        \\        _ = msg;
        \\    }
        \\}
        \\fn use8(v: u8) void {
        \\    _ = v;
        \\}
    ;
    var run = try runIntCastTest(&diag, allocator, "app_invalid_cont.zig", content);
    defer run.deinit(allocator);
    try std.testing.expectEqual(
        @as(usize, 0),
        countRuleIssues(run.issues.items, "app_invalid_cont.zig", RULE_INTCAST_NO_BOUNDS),
    );
}

// ============================================================================
// Strict CI gating (--strict / --fail-on / config strict/fail_on)
// ============================================================================

test "computeExitCode: default (never) passes with warnings" {
    const counts = PrintCounts{ .warnings = 1 };
    try std.testing.expectEqual(@as(u8, 0), computeExitCode(counts, .never));
}

test "computeExitCode: strict fails on a single warning" {
    const counts = PrintCounts{ .warnings = 1 };
    try std.testing.expectEqual(@as(u8, 1), computeExitCode(counts, .warning));
}

test "computeExitCode: notes-only does not fail strict" {
    const counts = PrintCounts{ .notes = 3 };
    try std.testing.expectEqual(@as(u8, 0), computeExitCode(counts, .warning));
}

test "computeExitCode: fail-on=note fails on notes only" {
    const counts = PrintCounts{ .notes = 1 };
    try std.testing.expectEqual(@as(u8, 1), computeExitCode(counts, .note));
}

test "computeExitCode: fail-on=error passes with warnings only" {
    const counts = PrintCounts{ .warnings = 5, .notes = 2 };
    try std.testing.expectEqual(@as(u8, 0), computeExitCode(counts, .err));
}

test "computeExitCode: fail-on=error fails on an error finding" {
    // errors are a subset of warnings (lumped), so both fields are set
    const counts = PrintCounts{ .warnings = 2, .errors = 1 };
    try std.testing.expectEqual(@as(u8, 1), computeExitCode(counts, .err));
}

test "computeExitCode: error findings also fail the warning level" {
    const counts = PrintCounts{ .warnings = 1, .errors = 1 };
    try std.testing.expectEqual(@as(u8, 1), computeExitCode(counts, .warning));
}

test "computeExitCode: clean run passes at every level" {
    const counts = PrintCounts{};
    inline for (.{ .never, .err, .warning, .note }) |level| {
        try std.testing.expectEqual(@as(u8, 0), computeExitCode(counts, level));
    }
}

test "PrintCounts.add accumulates the error subset" {
    const a = PrintCounts{ .warnings = 2, .notes = 1, .errors = 1 };
    const b = PrintCounts{ .warnings = 3, .notes = 2, .errors = 2 };
    const total = a.add(b);
    try std.testing.expectEqual(@as(usize, 5), total.warnings);
    try std.testing.expectEqual(@as(usize, 3), total.notes);
    try std.testing.expectEqual(@as(usize, 3), total.errors);
}

test "FailOn.fromString round-trips and rejects garbage" {
    try std.testing.expectEqual(FailOn.never, FailOn.fromString("never").?);
    try std.testing.expectEqual(FailOn.err, FailOn.fromString("error").?);
    try std.testing.expectEqual(FailOn.warning, FailOn.fromString("warning").?);
    try std.testing.expectEqual(FailOn.note, FailOn.fromString("note").?);
    try std.testing.expect(FailOn.fromString("warn") == null);
    try std.testing.expect(FailOn.fromString("") == null);
}

test "config strict:true sets the warning gate" {
    var diag = testDiagCtx();
    var cfg = testConfig();
    try parseConfigJson(&diag, std.testing.allocator, "{\"strict\": true}", &cfg);
    try std.testing.expectEqual(FailOn.warning, cfg.fail_on);
}

test "config strict:false leaves findings informational" {
    var diag = testDiagCtx();
    var cfg = testConfig();
    try parseConfigJson(&diag, std.testing.allocator, "{\"strict\": false}", &cfg);
    try std.testing.expectEqual(FailOn.never, cfg.fail_on);
}

test "config fail_on parses the level" {
    var diag = testDiagCtx();
    var cfg = testConfig();
    try parseConfigJson(&diag, std.testing.allocator, "{\"fail_on\": \"note\"}", &cfg);
    try std.testing.expectEqual(FailOn.note, cfg.fail_on);
}

test "config error_naming defaults to TitleCase when absent" {
    const cfg = testConfig();
    try std.testing.expectEqual(ErrorNaming.title_case, cfg.error_naming);
}

test "config error_naming parses snake_case" {
    var diag = testDiagCtx();
    var cfg = testConfig();
    try parseConfigJson(&diag, std.testing.allocator, "{\"error_naming\": \"snake_case\"}", &cfg);
    try std.testing.expectEqual(ErrorNaming.snake_case, cfg.error_naming);
}

test "config error_naming parses TitleCase and the PascalCase alias" {
    var diag = testDiagCtx();
    var cfg_title = testConfig();
    try parseConfigJson(&diag, std.testing.allocator, "{\"error_naming\": \"TitleCase\"}", &cfg_title);
    try std.testing.expectEqual(ErrorNaming.title_case, cfg_title.error_naming);

    var cfg_pascal = testConfig();
    try parseConfigJson(&diag, std.testing.allocator, "{\"error_naming\": \"PascalCase\"}", &cfg_pascal);
    try std.testing.expectEqual(ErrorNaming.title_case, cfg_pascal.error_naming);
}

test "config error_naming unknown value warns and keeps the default" {
    var diag = testDiagCtx();
    // Mute the warning print: zig's test runner surfaces stderr as failure.
    diag.cli_diagnostics_enabled = false;
    var cfg = testConfig();
