test "findPathDirInContent skips comments and rejects unsafe candidates (RED4-2)" {
    // A hostile comment line must not win over a later real match.
    const hostile_comment =
        \\// root_source_file = "/abs/evil.zig"
        \\const std = @import("std");
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("src/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(hostile_comment));

    // A ".." candidate in a comment line is skipped like any comment.
    const parent_comment =
        \\// root_source_file = "../outside/x.zig"
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("lib/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("lib", findPathDirInContent(parent_comment));

    // An absolute candidate in real code is rejected, not selected.
    const absolute_code =
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = "/opt/evil/main.zig" });
        \\    const lib = b.addStaticLibrary(.{ .root_source_file = b.path("src/lib.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(absolute_code));

    // A ".." candidate in real code is rejected by the component check.
    const parent_code =
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("../outside/main.zig") });
        \\    const lib = b.addStaticLibrary(.{ .root_source_file = b.path("src/lib.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(parent_code));
}

test "findPathDirInContent masks trailing comments and string bodies (EPH-I0144)" {
    // A payload in a trailing comment on a code line must not win over a
    // later real match.
    const trailing_comment =
        \\const b = std.Build; // root_source_file = "evil/x.zig"
        \\pub fn build(b2: *std.Build) void {
        \\    const exe = b2.addExecutable(.{ .root_source_file = b2.path("src/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(trailing_comment));

    // A real match keeps its value when a comment follows it.
    const real_then_comment =
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("src/m.zig") }); // note
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(real_then_comment));

    // A `//` inside a string literal is not a comment. The quote-aware
    // strip must keep such a line whole.
    const url_own_line =
        \\const url = "https://example.com";
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("src/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(url_own_line));

    // Same-line form: a naive strip would cut at the string's `//` and
    // hide the pattern after it.
    const url_same_line =
        \\pub fn build(b: *std.Build) void {
        \\    _ = "https://x"; exe.root_src = "src/m.zig";
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(url_same_line));

    // A payload on a line-initial `\\` multiline-string body line stays
    // skipped. The existing skip already covers this shape; this pins it.
    const string_body =
        \\pub fn build(b: *std.Build) void {
        \\    const note =
        \\        \\root_source_file = "evil/x.zig"
        \\    ;
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("src/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(string_body));
}

test "config trust: cwd and ancestors trusted, descendants untrusted" {
    try std.testing.expect(isConfigDirTrusted(std.testing.io, "."));
    try std.testing.expect(!isConfigDirTrusted(std.testing.io, "src"));
    // The working directory's parent is an ancestor, hence trusted.
    var buf: [Fs.max_path_bytes]u8 = undefined;
    const cwd = try Fs.cwd(std.testing.io).realpath(".", &buf);
    const parent = std.fs.path.dirname(cwd) orelse return error.TestUnexpectedResult;
    try std.testing.expect(isConfigDirTrusted(std.testing.io, parent));
}

test "untrusted target config keeps suppression and gate keys off (RED3-1/2/6/8)" {
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const dir_path = try tmpDirPath(allocator, &tmp);
    defer allocator.free(dir_path);
    try writeTestConfig(dir_path, "{\"disable\": [\"Z\"], \"exclude\": [\"\"], " ++
        "\"fail_on\": \"never\", \"strict\": true, " ++
        "\"thresholds\": {\"max_function_lines\": 100000}, " ++
        "\"error_naming\": \"snake_case\", \"entries\": [\"src/main.zig\"]}");
    // EPH-I0195: the untrusted entry must resolve inside the scan root to
    // survive the containment gate.
    try tmp.dir.createDirPath(std.testing.io, "src");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "src/main.zig",
        .data = "pub fn f() void {}\n",
    });

    var cfg = testConfig();
    defer cfg.deinit(allocator);
    // Production shape: cfg.path IS the target dir (the containment root).
    try setOwnedPath(allocator, &cfg, dir_path);
    diag.cli_diagnostics_enabled = false;
    try loadConfigFromTargetPath(&diag, allocator, &cfg, cfg.path);

    // Suppression and CI-gate keys are ignored...
    try std.testing.expectEqual(@as(usize, 0), cfg.disabled_rules.items.len);
    try std.testing.expectEqual(@as(usize, 0), cfg.exclude.items.len);
    try std.testing.expectEqual(FailOn.never, cfg.fail_on);
    try std.testing.expectEqual(@as(usize, 50), cfg.thresholds.max_function_lines);
    try std.testing.expectEqual(ErrorNaming.title_case, cfg.error_naming);
    // ...with exactly one note for the whole file...
    try std.testing.expectEqual(@as(usize, 1), diag.untrusted_config_note_count);
    // ...while analysis keys stay honored (entries made absolute).
    try std.testing.expectEqual(@as(usize, 1), cfg.entries.items.len);
    try std.testing.expect(mem.startsWith(u8, cfg.entries.items[0], dir_path));
}

