    const allocator = gpa.allocator();

    // EPH-I0111: the if arm does not fill x, so the c-true path reads
    // undefined. The CFG events fire on the one-liner, but the blocks
    // must split the shared line at the arm boundaries.
    const content =
        \\fn use(v: u32) void {
        \\    _ = v;
        \\}
        \\fn f(c: bool) void {
        \\    var x: u32 = undefined;
        \\    if (c) {} else { x = 2; } use(x);
        \\}
